local _, ns = ...
ns.chapters = {
  [529] = {
    start = { title = "In the Light", { "Come in, come in! No, stand there, in the light, where I can see you properly." }, { "You have the look of someone who can swing a weapon and has not yet been told what for. That is where I come in. The Dawn has one enemy, the dead, and no interest at all in which of the living you came from. Take our commission. What the Scourge carries on it is of great interest to me, and then we shall know what you are." }, { "One more thing. Everything in this world that is pushed too far becomes its own enemy. Courage. Faith. The Light itself. Remember that. I shall ask you about it later." } },
    friendly = { title = "Insignia", { "You have been about the Plaguelands long enough now that we may talk as colleagues." }, { "Do you know what they carry, the dead? Insignia. The Scourge is an army, and an army has ranks, even when its soldiers are dead. The common stones mark its rank and file. The rarer mark its elite. The rarest belong to its masters, the creatures that give the orders, and they are worth a great deal more than the rest. I keep the count. Some nights it is the only proof I have that we are winning." }, { "Every set brought to me earns a token. Somewhere in the Plaguelands, a thing that once took orders has stopped taking them. That gives me a great deal of satisfaction. I suspect that says something about me, and I have no intention of finding out what." } },
    honored = { title = "A Spine of Iron", { "I promised to ask you about extremes, and I keep my promises. What do you call a man who fights the Scourge, prays to the Light, and kills the innocent because he will not trouble to tell them from the guilty? The Scarlet Crusade calls him a crusader. I call him a blasphemer!" }, { "They hold part of Stratholme. Inside it, a man named Galford keeps their archive, years of what they are pleased to call intelligence." }, { "I want it burned. I want him dead. Tell me that is unreasonable. Go on.", before = 5251 }, { "You burned it for me, and that night I slept better than I have in years. Tell me that was unreasonable. Go on.", after = 5251 }, { "You see, we of the Dawn are tolerant. Tolerance is not softness. It needs a spine of iron, or the first fanatic to come along will bend it double. I have a spine of iron." } },
    revered = { title = "Those Who Come Back", { "You will have noticed that I am always here when you return. I send. That is what I do. I send people like you into Stratholme and the dead fields, and I wait at Light's Hope and count what comes back, the stones and the people. The stones always come back." }, { "So I keep two counts. The stones go in the ledger, where the quartermasters can see them. The other count I keep nowhere at all, and I could recite every line of it to you." }, { "You will also have noticed that I never call the Scourge's rank and file weak. I learned why from the ones who did not come back." }, { "Naxxramas is up there, Kel'Thuzad's citadel, and the Dawn will send people into it. Some of them will be people I sent somewhere else first." }, { "And you brought me a demon's head out of Stratholme, and I have not yet decided what it means. Those people in red believed they served the Light. They were serving a dreadlord. I called them blasphemers. I should like to know what to call them now.", after = 5262 } },
    aside = { title = "A Dangerous Habit", { "You are here again. I have stopped being surprised, and I warn you that this is the first step towards depending on you." } },
    exalted = { title = "Champion", { "Champion." }, { "Kneel. No, do not kneel. I am not a king, and you would only get up again with that look on your face." }, { "I have not called anyone that in years. I do not use the word loosely. I do not use anything loosely, as you may have noticed." }, { "I told you once that everything pushed too far becomes its own enemy. I have thought about it a great deal since. That is your fault. I am a man who would burn a library for the Light and call the smoke a sermon. Anyone in this chapel may yet become what he hates, my friend, and the likeliest of them is me." }, { "That is why I need you. A champion is someone I trust to tell me when I have gone too far, and whom I will believe, however little we agree. I have not had one for a long time." }, { "The war is not over. One day the Dawn will go against the master of all this, wherever he sits, and I will stand before its ranks with a sermon I have never once managed to finish. Someone will have to stop me. I would rather it were a champion." } },
  },
  [576] = {
    start = { title = "The Door", { "I saw you coming up the road. You want the tunnel. Strangers always want the tunnel, because it is shorter than the mountains. It is not yours." }, { "We are the Timbermaw, the last tribe the corruption has not taken. You have met the others. Everyone has, and everyone shoots first now, without stopping to look. So do we." }, { "Grazle will tell you how to change our minds. Grazle tells everyone everything. Do what he asks, and then do it again." }, { "I will be here, at the door. I have one eye. For you, it is enough." } },
    friendly = { title = "The Count", { "From here on, it is counting." }, { "Feathers off the headdresses of the Deadwood, to Nafien at the gate or to Grazle, for those who bring them. They tell me the count whether I ask or not. I do not enjoy it. The Deadwood were our kin before the fel got into Felwood and into them, and a feather does not say which of them it was." }, { "The beads are worse. The Winterfall carried them against foul spirits. You can see how well that went. They wore their wards, the foulness walked in anyway, and now their beads go to Salfa in strangers' bags." }, { "Salfa thinks you are useful, and Salfa is seldom wrong. I still watch you." } },
    honored = { title = "What Few Have Asked", { "You have walked the hold so often now that the guards no longer reach for anything when you pass. So take this, and do with it whatever your kind does with things it is told." }, { "The night elves took our help once, against the demons, and many of them took it holding their noses. Some of them have not stopped. Ask the Sentinels, on a day they feel honest." }, { "The Winterfall were our friends, and not long ago. Then their high chief began to want things nobody understood, and his tribe turned on everyone near it, us with the rest. Since then we keep to ourselves. We learned that much." }, { "Your people write their history down. We do not. And what we hold dearest, you have walked through a hundred times without seeing. Not yet." } },
    revered = { title = "Said Once", { "You will not repeat this to Grazle." }, { "We cannot hold this place alone. Salfa tells strangers so, because Salfa is honest to a fault. I say it to you because you are not a stranger any more. If the Winterfall and the Deadwood came at us from two sides at once, we would need every friend we have, and there are not many." }, { "Your kings have sent word to this hold before. The dwarf king under his mountain. The warchief of the orcs, in Durotar. They wanted to talk. There was no peace. I could give you the reasons, but you would not like them, and most of them would be about your people." }, { "You are Revered among us. Here the word means something plainer than it does among you. It means that if you fell at the door, someone would come out for you. It would be me. I would complain the whole way." } },
    aside = { title = "Salfa Says", { "Still here. Still counting. Salfa says you are halfway to something. Salfa likes saying things like that. When you have arrived, you will hear it from me." } },
    exalted = { title = "Walk Slower", { "Walk slower through the hold from now on. You will, once you know why." }, { "You think this place is a road. A good road, out of the snow, with furbolgs in it who have learned not to shoot you. It was never a road. The hold was made for Ursoc and Ursol, the twin bears we honour, and every tunnel you have hurried through to save yourself a mountain is part of it. We let those we trust walk through a holy place. Most of them never knew what it was. Now you do." }, { "You will ask about the eye. Everyone who gets this far asks about the eye. No." }, { "I was the last in this hold to trust you, and I would like that remembered, because I was right to be slow. Trust that comes easily leaves the same way. Mine came the slow way, and it is not going anywhere." }, { "There is one more thing, and we do not give it to many. In a bad hour, far from here, one of our ancestors will come and stand with you, and mend you while it fights. Not for small hours. They are old, and they are ours, and they come as a favour to me.", after = 8481 } },
  },
  [59] = {
    start = { title = "Insects", { "An insect. At my table. Speaking to me." }, { "We have no business with insects, and I have no patience for them. You have nothing I want, you know nothing I need, and you are blocking my view of the door. The Brotherhood walked out on the emperor long ago. I still drink in his city. Neither is your business." }, { "The Brotherhood keeps a house at Thorium Point for strays, where they are kinder. Be a stray there first. If they ever learn your name, come back, and I will consider learning it too." }, { "Until then, away. Away." } },
    friendly = { title = "Terms", { "Thorium Point knows your name. So. Stand where I can see you, and hear the terms." }, { "We went down into the Fire Lord's halls once, for his cores and his leather and the blood of the mountain, which is his own tears. Many of us went down and did not come up again. Now you go. You are cheaper. Nothing personal. At TB Ltd., nothing ever is." }, { "Favour opens the Brotherhood's books, the plans and patterns nobody else in this world will sell you. It is the one coin I take that does not tarnish. Gold I can have from anyone." }, { "The offering is weighed. The offering is found sufficient. Do not let it go to your head." } },
    honored = { title = "The Small Knife", { "The Brotherhood receives you, and acknowledges your... oh, never mind the form. Nobody gets this far with me. That is how you know it is an honour." }, { "You think we are Dark Irons who grew a conscience. Half of that is right. We were a guild before we were anything else, a craft guild in Ironforge, when there was one Ironforge and the clans had not yet gone to war over it. A frightened guild. We were sure our rivals knew secrets we did not. So we got hold of their best work and took it apart to see. That is how we found enchantment: by theft, and patience, and a very small knife." }, { "When the war came and the clans chose sides, we chose. You know which. I will not apologize for it to a stranger, and I am still deciding what you are, so I will not apologize to you either." }, { "Our best secret, we stole first." } },
    revered = { title = "The Waste", { "The Brotherhood will hear your question. No. I will." }, { "You want to know why we left. The long version, then." }, { "When the Fire Lord woke, the mountain was his, and so were we. The emperor's people became his servants, and the Brotherhood became his smiths. We worked his forges. We made his weapons, the same blade over and over, for an army that did not care how well a thing was made. Understand me. Dwarves can bear cruelty. The waste broke us. The finest hands under the mountain, hammering out the same sword for creatures who could not tell it from a worse one." }, { "It was my apprentice who found the way out. Oilfist. Overseer Oilfist now, at Thorium Point, running the place like a garrison. He planned it under the overseers' noses, and we made what we needed to walk out of the Depths. Most who got free ran as far as their legs would carry them. We stopped across the Gorge. The materials are here. Craft does not run." }, { "And why am I here, at a table in the emperor's own city? The ale. Next question." } },
    aside = { title = "The Better Chair", { "You again. Sit. No, not there. There. You have earned the better chair. It is the same chair, but I will know." } },
    exalted = { title = "Partners", { "No more ceremony. You and I are past weighing offerings. Listen. From now on I talk to you without it." }, { "The Brotherhood holds the secret of the Fire Lord's hammer. Sulfuras. The great maul he carries down there in the Core. We can teach a smith to forge the Sulfuron hammer, and with the Eye of Sulfuras set into it, a hero could carry the Hand of Ragnaros out into the world. Think about what that means. We spent an age making weapons for him. Now we sell the making of his own to anyone strong enough to kill him, at a fair price. I have never been so pleased with a piece of business in my life." }, { "I lose my head about it. Put a Sulfuron ingot in front of me and I will shout. I know. I do not care." }, { "The other thing, now you are past the door. A guild like ours does not live on craft alone. When a rival grows too good, now and then, his forge has an accident. We are never anywhere near it. You will remember that we are never anywhere near it." }, { "You came to my table an insect. You leave it a partner. Read your contracts, all of them. Mine especially." } },
  },
  [609] = {
    start = { title = "The Other Enemy", { "Welcome to the Hold! Everybody here watches the bugs. They're big, there are a great many of them, and they sit in their hives and behind that wall as if they're waiting for something, so I don't blame anyone for watching." }, { "But turn around. The cultists out in the desert aren't waiting. They're building, and calling, and passing each other notes in scribble. My big brother Huum and I stay on them, because somebody has to and nobody else will." }, { "Bugs, we've got plenty. A real fight, I've got better." } },
    friendly = { title = "Scribbles", { "The cult's papers are what I want most. Little scraps covered in scribble. That's how their camps talk to each other!" }, { "I can't read them, and I don't need to. Every stack taken off a dead cultist is a message that never arrives, an order nobody gets, a camp waiting for word and hearing nothing. That's a fight too. A quiet one, but a fight." }, { "Huum would want to read them. Huum listens to things, the land, the spirits, papers too, I expect. Me, I stash them. Someday someone clever will want them, and until then every scrap in my stash is one the cult never gets to read." } },
    honored = { title = "My Big Brother", { "Here. You've earned a story, and I've got one, and it's mostly about my brother." }, { "My people, I always say, do things slowly, listening first. Huum is one of my people all the way through. Huum listens first. He says the spirits here are calling him, and the sand is grieving over something it needs someone to hear." }, { "I don't hear it. I've tried, hard, the way I try everything. I stand where he stands and all I get is sand in my ears. But I believe him. Because he's my brother. Because I've never once managed to prove him wrong. And because when he goes quiet in the evening, he stays quiet too long." }, { "So I fight, and he listens, and between the two of us the Hold has what it needs." } },
    revered = { title = "What They Call Up", { "What keeps me up at night is a short list. It keeps me up, so it can keep you up too." }, { "The cult isn't only praying out there. They're calling things up out of the summoning stones: templars, then dukes, then lords, each one bigger than the last and each one a bigger headache for me. And each one hands down orders. We know they can be smashed. What we don't know is who they answer to. Maybe the cult worships them. Maybe they're only messengers, and whatever sends the messages hasn't shown itself yet." }, { "So, the list. The bugs in their hives and behind the wall. The cult in the desert. Whatever the cult calls up. Whatever has Huum so quiet in the evenings. That's a lot of enemies for one stretch of sand." }, { "Everyone tells me to wait and watch. I've been waiting and watching a long time. It hasn't grown on me." } },
    aside = { title = "My Post", { "Same post, same sand. Go wrestle the big ones for me, and come back and tell me how hard they hit!" } },
    exalted = { title = "The Biggest Chest", { "You know what I'd give you, if I could give you anything? My post. Just for one day." }, { "That chest was no use at all as a thank you. I heard you laugh when you opened it, and I know it wasn't the chest you were laughing at.", after = 8352 }, { "I'd walk out of the Hold with you, past the camps and the stones and out into the desert, and we'd find the biggest thing the cult can call and find out together how hard it hits!" }, { "I can't. Someone has to stand here, and it's me. It's always been me. So I stay, the way I always have. When Huum goes quiet in the evening, I watch him. Him, not whatever he's listening to. His ears go still, his breathing slows, and he's somewhere I can't follow. He's the one I'm guarding. The Hold, the wall, the papers, all of it, I'd trade for him without a second thought, and that's a terrible thing to say when you're standing guard." }, { "Huum would tell me the land needs guarding more than he does. Huum would be right. He usually is. I'd still pick him." } },
  },
  [270] = {
    start = { title = "Not Yet", { "Welcome. They call me Rin'wosho, and I trade out of Zuldazar, a long way from home and further still from my best customers." }, { "You will want to see what I carry. Everyone does. Goods of the South Seas, patterns for your tailors and your leatherworkers, fruit you have never tasted. And I would love to sell them to you. But I barter only with friends of my tribe, and you are not one yet." }, { "The Zandalar are at war with a god who should have stayed gone. Help them in that, then come back, and we will talk prices." } },
    friendly = { title = "Honour, in Coin", { "Now we can do business, my friend." }, { "Among the Zandalar it goes like this. What you carry out of Zul'Gurub for the tribe, the tribe repays in honour, in tokens to keep and to spend with me. I like a people whose gratitude fits in a purse. Spend them or keep them, as you please. I have known people keep one for years, for no reason they could name." }, { "The trolls of Zul'Gurub carry coins of their own, one kind for each of its tribes, every one thick with mojo, and Vinchaxa takes them for the tribe's use. I would not haggle over those. Some things are worth more than they buy." } },
    honored = { title = "The Mango", { "You have never eaten an essence mango. Nobody who has tasted one asks what it is." }, { "They grow wherever the South Seas have a beach to grow on. One of them and you are rested, body and thought together, as if you had slept a night on the sand at home. I keep a supply here on the isle for those the tribe has come to respect. I could sell them here for a small fortune. I do not. Some fruit is only for friends." }, { "I do not miss Zuldazar for its king or its priests. I miss it for the fruit, and the sea, and my own language spoken by people who are not afraid. Here everyone is afraid. You can hear it in how quietly the isle talks once the sun is down. Here even the fruit tastes a long way from home." } },
    revered = { title = "What the Priests Took", { "With your standing come my most potent brews, the ones Zanza has blessed. Take one at a time, my friend. A blessing is not a thing you stack." }, { "Why does the tribe hand its blessings to outsiders at all? In Zul'Gurub the high priests are the Soulflayer's thralls, and through them he drinks our gods, their strength rather than their blood. Every day he holds that city, the oldest powers my people know grow a little weaker, and he a little stronger, and no one can tell me where the bottom of that lies." }, { "I sleep badly on this isle. A merchant knows what leaves his shelves, and I can no longer reckon what leaves the gods. Some nights I walk the beach and talk to the sea in my own language, so that something on this isle still hears it." }, { "So when I hand you a blessed brew, call it stock moved before the warehouse burns." } },
    aside = { title = "Regular Customer", { "A mango? Careful. A merchant who serves the same customer twice grows fond of them, and fondness is very bad for prices." } },
    exalted = { title = "From Home", { "These I sell to no one else. Signets, carried across the water from the South Seas, for the shoulders of those the tribe counts as its own. Might, mojo or serenity: I have fitted a great many shoulders in my life, and few of them carried anything worth the weight." }, { "Under every trade we have made lies one plain thing. The coins go into the tribe's defence against the god in Zul'Gurub, and the bijous are broken on Zanza's altar, every scrap of mojo turned against him. For a long time I told myself I was only selling. I stopped believing it some while ago. I think it was about when I began keeping the best mangoes back for you." }, { "I will go home one day, when the Soulflayer is ash and our gods are whole again. The sea will still be there. It is the one thing I have never had to bargain for. The first evening, I will eat a mango on the sand and think of this ugly little island, and I suspect I will miss it. When I go, I will tell them about you, and about your bargains." } },
  },
  [910] = {
    start = { title = "Beneath Notice", { "You need not lower your voice. Little that mortals say carries far among my kind. The bronze flight has not favoured one of you in a very long while, and you begin with us where every mortal begins: nowhere at all." }, { "Do not take it hard. We are slow to attend to anything that will not last, and that is all it is." }, { "There, past the walls of the Hold, the hive is moving. The ground around it trembles, and the old enemy readies its war again. That is the thing worth minding. It is why I am here." } },
    friendly = { title = "Grains", { "So. You have begun to matter, a little. I felt it as one feels a single grain slip in an hourglass: hardly at all, and then there is no ignoring it." }, { "What the flight wants of mortals is simple and very hard. Every servant of the insects' masters that falls is a grain moved from their side of the glass to ours. I have tended that glass a long time. It is good to see another hand on it." }, { "A word about the bronze flight, which you have not asked for: we do not hurry. That is not the same as not caring. Remember it, the day we seem slow to you." } },
    honored = { title = "The Breath", { "I will give you an old story, if you will take it. I will tell it without ornament." }, { "I was dying once. I had nothing left to give, my wounds were open, and I was no longer afraid, which is how I knew how near the end had come. Then the master of my flight came to me." }, { "I do not remember the breath. I remember that afterwards I was no longer dying, and that I was told to remain, for as long as remaining was needed. So I became a Watcher. I have never found a better word for it than the one I was given." }, { "It was kindly done, and it has cost me ever since. Both of those are true, and I have stopped trying to make one of them smaller than the other." } },
    revered = { title = "The Oath", { "Long ago I swore an oath, and the time to keep it has come at last. What it was is mine. What keeping it feels like, I can give you." }, { "It feels like a door you have watched for so long that you forgot it could open. The hive stirs, the sands shift, the qiraji make ready, and all at once the waiting is over, and I wish it were not. An oath kept is an oath you no longer carry. I have carried this one so long that I do not know my own weight without it." }, { "A Watcher fears one thing, and it is not the enemy. The enemy is honest. What a Watcher fears is the thought that the one you wait for will not come back, and that you will go on waiting anyway, out of habit, long after it means anything." }, { "I have had that thought every day for longer than your kind has had names." } },
    aside = { title = "The Hourglass", { "Halfway by your reckoning. By mine, a moment. Neither of us is wrong. Go on. The glass does not mind." } },
    exalted = { title = "Favour", { "The bronze flight has let its sand run past every mortal who has stood in this desert since the wall went up, and in all that running I had given up on its ever pausing for one. I thought of it the way one thinks of rain here: idly, out of habit, without hope." }, { "It has paused for you, and that means I will stop speaking to you as I speak to a stranger. To me that is a great deal. For a very long time everyone I spoke to was a stranger, even those beside me, as though some part of me were always turned towards the wall." }, { "You went to the Caverns of Time for me and found the master returned. My watch is over. I do not yet know what a Watcher does when the watching ends. Stay a while, and help me find out.", after = 8286 }, { "I have waited a long time for something to arrive, and long ago I stopped picturing what shape it would take. It came with sand in its boots, and it waited with me. Waiting with someone beside me is a different thing, and I had forgotten how different. Whenever you return, however late, I will know you. I am glad to have been wrong about mortals, and the sand will go on falling, a little more gently now." } },
  },
  [749] = {
    start = { title = "A Bargain", { "You were not born in water, and what we fight over will always be closed to you. Nothing here will be made clearer by pretending." }, { "A bargain needs no understanding. The Waterlords fight the lords of air, of earth and of fire, and it is fire we cannot forgive. You are small and short-lived, and you walk on land that burns. You have reasons of your own to want the fire put out. Your reasons and ours may run the same way for a while. I mean to use that." }, { "Prove useful, and the deep will remember you. It forgets almost everything." } },
    friendly = { title = "Purity", { "You have been useful. That is rarer than you would think, among your kind." }, { "Understand what we fight for. You are beside us now. What makes us strong is that we are pure. Water that takes in whatever it touches is no longer water, only a sickness that flows. When the plague of Lordaeron got into the elementals we sent there, what offended me was what they had become." }, { "Of one thing I know nothing. Our enemies of air and earth guard objects of power in the south, away from mortals, and I cannot tell you why. I know only that whatever they keep, I would rather they did not." } },
    honored = { title = "The Debate", { "They spoke of you in our chambers, and at length. That is not our way. You were the subject, not the judge, and it is right that you hear how it went." }, { "Some among us thought you a poor thing to spend on our war, a creature we would pour strength into only for it to crack. They were not wrong, and they are not wrong now. You are small. You do break. You came back anyway, against our enemies, again and again, and each return made their view a little harder to hold." }, { "None of us thought it possible. The Waterlords respect you now. It troubles the order of things in a way I have no word for, because a small thing should not weigh this much, and you do. The doubters have gone quiet, the way a current goes still before it turns." } },
    revered = { title = "The Loss Judged Worth It", { "The water has no mercy and no malice. I will speak the way it does." }, { "It costs us to lose a hand that has proved itself, and you have. To send one of you against the Firelord's own captains is the hardest thing we ask, and we ask it only when the gain is judged worth the loss. That judgment is the highest compliment the Waterlords know how to pay. I would not blame you for not hearing it as one. We have spent agents before, and the water closed over them. It would not close so quickly over you." }, { "Beneath the mountain the floor is cut with runes of fire. Each one is a door to its realm, and each one feeds it. When a rune goes out, one door shuts, the fire draws a little less from home, and it is a little more alone in the world. That is all we want of it: that it be alone, and then that it be gone." } },
    aside = { title = "The Tide", { "The tide has turned a little in our favour, and some of that is your doing. A little. It is a large tide, and you are a small creature, and still it moved." } },
    exalted = { title = "Legend", { "Gratitude is a mortal habit. Among us, nothing is owed for work well done. The current does its work and no one praises it for that. The sea does not thank the river for arriving." }, { "You have fought for us with a steadiness I did not think a creature of your size could keep, and I want to give you something. I tried to think what one of you would want, and could not. So I give you what we would want, if we wanted anything. It is as much thanks as the deep can give, and I am told that among your kind it is customary to say so aloud, so I have. Take it, then: a source of our quintessence that will not run dry. I do not set a term." }, { "You brought me the hands of the Firelord's captains. Word of it ran down through our deep halls like a current. I did not think one so small could become a legend here. You are one already.", after = 6824 }, { "You are small, and you will not last. I still think both of those things. The deep forgets almost everything. It has decided to keep you." } },
  },
  [809] = {
    start = { title = "Who Are You Again", { "Ah. A visitor. How novel. No, do not tell me your name. I would only have to forget it, and that is such an effort, and the catalogue will not keep itself." }, { "When one has kept the index of a house for ten thousand years, a mortal's hour grows very small, and your troubles, whatever they are, shrink with it. I say that without malice. I say most things without malice. It saves time." }, { "Every tome in these halls bears the house's seal, and far too many of them are not where they belong. Bring one back, and I may begin to remember you." } },
    friendly = { title = "Party Tricks", { "The librams, then. Those are what I want from you." }, { "Some years ago an elf of Quel'Thalas came to us, Master Winthalus, fleeing the ruin of his homeland with a few old treasures. He then mislaid them about these halls with a carelessness I can only call heroic. Each libram holds a little spell for your gear. Party tricks. Still, bring me one with the reagents it asks, and I will make you its arcanum, and you may wear it and feel very slightly less mortal for an afternoon." }, { "Do not mistake my tone. The librams bore me, and I want every one of them back. Nothing written is worthless. It is the one belief I have kept whole in all my years, and I would thank you not to test it." }, { "Who are you again? It is coming to me." } },
    honored = { title = "The House", { "You insist on being underfoot, so you may as well know the house you are walking through." }, { "Master Winthalus sobbed over a lost libram. Sobbed. Over a protective cantrip. I have shed tears over a lost book myself. Losing what was known is the only grief I respect. But one weeps for a history, not for a party trick." }, { "The Prince had him flayed. I called it a favour at the time, and I have had a long while to wonder whether I meant it. That tells you something about this house, or about me, and I would rather not look into it." }, { "Then there is Azj'Tordin, who ran from the Prince, and an imp relieved him of his book of spells on the way out. He will die now, like any of you. And for what? Some fresh air and a great many trees." }, { "You are still here. How odd. Most visitors have the sense to leave by now." } },
    revered = { title = "The Index", { "The index is for something. Nobody has asked me what in a very long time." }, { "Everything this house has known since before the world broke is set down somewhere in these halls, and I know where. Every war, every spell, every foolish prince, every name. I keep the index so that if the Shen'dralar are one day gone, and I suspect that day is nearer than the Prince believes, what we knew will not go with us. The Prince likes to say he keeps the house alive. I keep what it knew. Of the two, mine will last longer." }, { "The Athenaeum is vast, and that is the least of it. It waits, for readers who never come. Bring me back one of our tomes and I may tear you out a page. Yes, I, who hold that nothing written is worthless. A page in a book nobody opens might as well be furniture. I would rather lose a page to a reader than a book to the dust. A mortal who carries one page out of here might one day come back for the rest." } },
    aside = { title = "Back So Soon", { "Back so soon? I had your hour set aside, between two very dull treatises. Do not read anything into it." } },
    exalted = { title = "Your Name", { "I know your name." }, { "Do not gloat. It is the first mortal name I have troubled to keep in an age, and I have filed it. For me that is as close as affection comes. I have filed it somewhere distinguished. You would not believe the company. Generals, poets, and one very tiresome queen." }, { "The entry is short. Your name, and beneath it a note in my own hand. It began as a single word, \"persistent.\" Later I added \"useful,\" and then, after a long argument with myself, \"welcome.\" I crossed that last word out once. It came back, and I have let it stay." }, { "You brought me back the dull old blade, and I told you what it would take to give it its edge again, dragon and all. I expected to see neither of you again. I was wrong, about you at least, and I am rarely wrong, and I have written that down too.", after = 7508 }, { "I have read nearly everything this house ever set down. Very little of it surprised me, and none of it lately. You did, a little, and more than once. Go and do something worth adding. I will be here with the index, being unbearable, and I have left room after your name." } },
  },
  [589] = {
    start = { title = "Meat", { "Hello. Not many climb this far, and those who do usually want a saber." }, { "You can have one in the end, but mine is only half the say. A saber on this rock decides for herself whether she will carry you, and no price changes her mind. You will have to win us both, and the cats are the harder half." }, { "So we start where every young saber starts, with food. They eat a great deal while they train. The chimaera and the bears of these hills carry plenty of meat. Bring me some. It is plain work, and it counts, and it will be the first of many times you do it." } },
    friendly = { title = "Again", { "Good meat. The sabers ate all of it." }, { "I will ask you for the same thing many times, and I want it done well each time. A young saber learns that way. The lesson comes round again until it stops being a lesson and becomes simply what the cat is." }, { "There is other work now. The Winterfall furbolgs have gone strange. They are frightened of everything, and frightened things kill whatever crosses them. I never raised a hand against them, and I had hoped never to. But they come too near the rock, and I do not want them near the young ones. Push them back. The young ones should not learn fear this early." } },
    honored = { title = "The Queen", { "There is an old story under all this, and you have earned it." }, { "Long ago the queen of the sabers was in the grip of rampaging giants, and Tyrande Whisperwind pulled her free. The frostsabers have been friends to my people ever since. The queen is called Shy-Rotam. I think of that rescue every time a cat lets me near her. It was an old kindness, and the cats have never stopped repaying it." }, { "The giants are not gone. The frostmaul are the same ones, and they are still close. I ask you to fight them in her name. To me it is a debt, and you would be helping to pay it. I would not ask it of someone the sabers still hissed at." }, { "I think better of you every time you climb up here." } },
    revered = { title = "The Cub", { "When a cub first comes to me, it will not eat from my hand. It takes the food from the snow once I have stepped back, and it hisses while it eats. I put the meat down every day, a little closer. One day it takes the meat from my fingers. I have never been able to tell which day it will be. I have only learned to keep putting the meat down." }, { "It came to me last night that I have been doing the same with you. The meat, the same errand over and over, the furbolgs, the giants. A little closer each time. I did not plan it. I know no other way to teach anything." }, { "The sabers know your scent now. When you come up the path, the young ones lift their heads and lay them down again. From a saber, that is a great courtesy." }, { "I should have asked whether you minded. You did not leave. With a cub, that is the answer, and I have taken it as yours." } },
    aside = { title = "Halfway", { "Halfway. The young ones no longer lift their heads when you come up the path. They know your step. It took me a whole year to get that far, the first time." } },
    exalted = { title = "The Saber", { "There is a saber for you." }, { "She is one I raised from a cub. Of all of them she took the longest to eat from my hand, and she was the most stubborn about everything after. I thought the two of you would understand each other. She bit me more than once before she trusted me. She has not bitten you at all. I take that as a sign." }, { "She will carry you wherever you ask, through any weather. She goes quiet if she is kept too long from the cold. Give her the snow now and then." }, { "On the first day I told you that you would have to win us both, and that the cats were the harder half. I had that the wrong way round. The young ones made their peace with you long before I did. I have lived among cats so long that a person takes me longer than a cub. You climbed up here anyway, day after day, the way I keep putting the meat down for them. It turns out I was the cub." }, { "Go gently the first time. She has never left the rock." } },
  },
  [72] = {
    start = { title = "The Effort", { "Friend! Yes, you. Stormwind needs you, or rather it needs your cloth. Very nearly the same thing!" }, { "Our stores of textiles have fallen to a state that frankly alarms me. Bandages, tunics, blankets, every one of them begins as cloth, and the city goes through it faster than anyone will admit at a council meeting. So we have an effort. A great, many-sided, thoroughly organized effort, and I have the honour of running it." }, { "Wool, silk, whatever you take off the bandits on the road. Leave it on the desk and I will see to the rest, friend! The citizens notice who gives. So do I. I keep very good records." } },
    friendly = { title = "Where It Goes", { "Every piece handed across this desk goes somewhere, friend, and I make it my business to know where. The orphanage, for one, by the Cathedral. The children of soldiers live there. Last winter a good deal of donated silk went to their blankets, and I went along with the cart, to check the paperwork. The matron counted every blanket against my list. Then the children took them, and wrapped themselves up, and went quiet in a way I have never managed to make a council go quiet." }, { "I have been asked, more than once, whether a city with soldiers to feed ought to spend its cloth on blankets for orphans. I always say that a city with soldiers has more orphans than anyone, and that a city that stops spending on them has forgotten what the soldiers are for." }, { "Some of that silk was yours. The ledger never lies.", after = 7791 } },
    honored = { title = "The Workroom", { "Friend! Come and meet the effort. The real one, I mean, not the ledgers." }, { "Every evening, in a back room near the Cathedral, the volunteers come in to sew. Widows of the guard. Apprentices from the tailors' shops, who are paid nothing and argue about seams as if they were. A retired sergeant who rolls bandages with one hand and tells the same old stories about Redridge. Everyone pretends not to have heard them." }, { "I keep their schedule. I keep their thread. I keep the peace between the widow who hems from the left and the apprentice who hems from the right. It is the hardest diplomacy in this city, whatever the council thinks." }, { "Your cloth comes through their hands. They talk about you, by the way. \"The big donor\", the sergeant calls you. I have tried to correct him to \"our valued contributor\". He refuses on principle. Your wool has been through more arguments in that room than the council has had all year.", after = 7791 } },
    revered = { title = "The First Bandage", { "My mother sewed for the Cathedral when I was small. She took me with her, and I learned to roll a bandage before I could write my own name. Tight at the start, loose at the end, never let it twist. My hands still do it when I am nervous, with whatever is on the desk. I have rolled up council minutes that way, and nobody missed them." }, { "She never ran anything. She worked at the end of a long table with a basket and did the work, and went home, and came back the next day. I run the effort. I write the forms and keep the ledgers and stand up at meetings. Some nights I think she would find all that very funny." }, { "I run this desk the way she rolled bandages. Tight at the start, loose at the end, never let it twist. I am not sure I would have taken the post at all, if not for her. I am very glad I did, most of all on the days somebody comes through that door with their arms full." } },
    aside = { title = "The Ledger", { "Friend, a new bottle of ink! The ledger drank the old one dry this week. No purchase has ever pleased me more." } },
    exalted = { title = "The Stockpile", { "Friend, I have a ribbon. A real one, blue, very fine, bought years ago out of my own purse." }, { "When I took this post, I meant to fill the stockpile. Every shelf, every crate, every corner of the storehouse, full to the ceiling, and that ribbon tied across the door. I had a date in mind. I had a speech. It was an excellent speech. It had a part for the council in it, and a part for the volunteers, and a pause for applause." }, { "The stockpile will never be full. I understand that now. As long as there is a city, there will be wounded, and as long as there are wounded, the cloth will go out the door as fast as it comes in. Once I would have called that a failure. Now I call it the effort, and I am proud of it." }, { "You understood that before I did, and you never asked me when it would be done." }, { "So the ribbon is going on your arm instead of on the door, if you will have it, and the speech is going in the drawer. I have read it to nobody, and I think it is better that way." } },
  },
  [47] = {
    start = { title = "Under the Mail", { "Cloth. In Ironforge. You'd think a city of stone and steel would have no use for it. You'd be wrong, and you'd not be the first." }, { "Every dwarf in mail wears wool under it, or the mail wears the dwarf. Every miner who comes up hurt needs binding. Every bairn born in these halls needs wrapping, same as anywhere. The mountain keeps the cold off us. It does nothing for the lads on watch outside it." }, { "Whatever you can do without, I'll use. I'll not thank you with speeches. I'll thank you by using every scrap." } },
    friendly = { title = "Posts in the Snow", { "Cloth comes to this desk, and I send it out. Up the passes, mostly." }, { "Dun Morogh's a hard place in winter, and we keep dwarves on watch in it all year, at the gates and the ridges and the roads down to the lowlands. They write back now and then. Not often, dwarves aren't writers. When they do, it's mostly to ask for socks, and I send them by the crate, because you'd be surprised what socks do for a soldier." }, { "Down the roads, too, to the lakes and the wetlands, where our soldiers hold the roads. Wet country. Wool rots there twice as fast, and they need it twice as much." }, { "A dwarf on a ridge in a blizzard needs wool before he needs anything else. Before ale, even, and I've never said that to a dwarf's face." } },
    honored = { title = "The Exiles", { "When Gnomeregan fell, the gnomes came down the mountain to us with nothing at all, and in the snow." }, { "Ironforge gave them its blankets first, before it gave them a roof, and I was one of the ones handing them out. The storerooms emptied faster that winter than any raid ever managed. We gave the wool off our own beds and the padding out of our own mail, and some of the old soldiers grumbled, and gave it anyway." }, { "I still have the first blanket I handed out. A gnome brought it back to me a year later, washed and folded, with a note thanking me for the loan. I'd not thought of it as a loan. It's in my drawer. I take it out on the cold nights." }, { "A good share of the cloth that crosses this table still goes to them, and nobody here says a word against it. The ones who were there that first winter see to that." } },
    revered = { title = "The Shield", { "Steelshield. You'll have wondered." }, { "My family carried shields, and I carried one too, till a Dark Iron hammer found my knee and decided otherwise. I can walk. I can't hold a line. So they gave me this desk, and I hated it." }, { "Making my peace with it was slow work. A shield covers one dwarf, and covers him well, if you're good. A bale of wool, sent up to the right ridge, covers a whole post. I worked that out one night with a ledger and a bottle, and I've not been sorry since. Well. Not often. My first year, I sent a crate of wool to the wrong ridge, and a post went cold for a week. I've never forgotten which ridge. I check every crate twice now." }, { "I still keep the old shield behind the door. Every so often I take it down and polish it, and think about the ones I stood beside, and then I put it back, and I go and count wool." } },
    aside = { title = "A Taller Stack", { "The stack in the storeroom is taller than my clerk now. He's taken it personally. I've told him to grow." } },
    exalted = { title = "What Keeps the Hard Part Alive", { "A lad came down off the high ridge last week. Half frozen, beard full of ice, sent down with a cough the post couldn't mend. He stood at this desk dripping on my ledger and told me the socks were the only warm thing on that ridge all winter. Every dwarf up there had a pair, he said, and he'd come to say so himself because nobody else would bother." }, { "Those socks were wool from this very storeroom. He's a good lad. He'll make a better soldier than I did, and a warmer one." }, { "So I did a thing I've been not doing for years. I took the old shield down from behind the door, and I gave it to him, for when he goes back up. It's a good shield. It was wasted on a wall. I'll not need it again. I've got this desk, and this desk has more dwarves behind it than any shield ever did." }, { "Steel wins the day. Wool wins the winter. I learned that one slowly, and you were standing at this desk while I learned it." }, { "Now, the lad's waiting for his socks. Pass me that crate." } },
  },
  [69] = {
    start = { title = "A Quiet Request", { "Good evening. If you would spare me a little of your time." }, { "My people have spent these last years building a home in a place that did not exist before. A tree, grown into the sky, with a city in its branches. You may admire it. Most who come here do. They rarely ask what it cost, or what it is still costing, and I would not burden a stranger with the account." }, { "We are short of cloth, gravely so, and the times give us no rest in which to weave our own. If you have any to spare, Darnassus would be grateful, and my people keep their gratitude a long while." } },
    friendly = { title = "The Sentinels", { "The cloth that comes to this desk goes south, across the water, into Ashenvale." }, { "The Sentinels hold the forest there against the Horde. The orcs come for the trees. The Sentinels come for the orcs. The quarrel is young, and already it feels old, and every season it needs more bandages than the one before." }, { "The Sentinels do not ask for much. They are proud, and they would rather bleed than be seen to need help. So the asking falls to people like me, who live in a quiet city and send cloth to a loud forest, and who are not proud at all when it comes to the Sentinels' wounds." }, { "Your cloth was on its way to them before you had left the terrace. I sent a note with it, saying who it came from. They will not write back. Sentinels never do. But they will know.", after = 7792 } },
    honored = { title = "The Cold", { "We did not use to feel the cold." }, { "Since the World Tree was first planted, we did not grow old, and we did not sicken, and the winter touched us lightly. Our weavers made cloth for beauty and for nothing else. A night elf might wear the same cloak for a lifetime, and a lifetime was a long thing." }, { "That ended in the Third War. We gave up what we were to save the world, and we would give it again. But that year we became mortal, and we have been finding out since what that asks of a body. A fever that does not break. An old elf shivering by a fire that would once have been enough. A wound that will not close on its own." }, { "So we need cloth now as we never did. For keeping each other alive. Our weavers make bandages now, and blankets, and plain warm things that will be worn through by spring, and they are learning to be proud of them." } },
    revered = { title = "A Young Tree", { "Teldrassil is very young. People forget that, because it is very large." }, { "We grew it in haste, in a hard time, and a hurried home settles slowly. A home made in haste is still a home, and I love it. But a young tree has young troubles, and a young city has more than its share. Things go wrong that would not go wrong in a place that had centuries to settle. What they are is ours to mend." }, { "On windy nights I climb to the high branches and listen to the tree creak, and I hope it is only growing." }, { "Every piece brought to this desk goes into the mending, somewhere. A blanket on a sick child in the Craftsmen's Terrace. A bandage on a druid who fell from a branch. Cloth for the dead, too. Our weavers had never made a shroud before. They make them now, and they make them beautifully, because they do not know how to make anything any other way." }, { "Some of it was yours. You did not know you were doing all that. You did it anyway.", after = 7792 } },
    aside = { title = "Patience", { "My weavers have started asking after you by name. They are not a talkative people. I consider it a high honour, and I hope you do as well." } },
    exalted = { title = "The Hem", { "Our oldest weaver has started leaving her hems loose." }, { "She has woven for longer than any human kingdom has kept records, and for all that time she made cloth to last forever. Tight hems, hidden seams, threads that would outlive whoever wore them. That was the art. A night elf's cloak was meant never to wear out, because the night elf was meant never to." }, { "Then cloth from every people started coming across my desk. Human wool, dwarven wool, gnomish silk, cloth woven by short-lived hands for short-lived bodies. She took it apart to learn it, the way a weaver will. And she found that mortal peoples hem their cloth loose, so it can be let out as a child grows, and mended when it tears, and patched, and handed on." }, { "She weaves that way now. All of my weavers do. Cloth made knowing it will not last, and made to be loved anyway." }, { "Strangers gave us cloth. In the hems, without meaning to, they also gave us a way of making it that fits what we are now. We needed both. I did not know how to thank them for the second, so I have asked her to hem you a cloak in the new way. It will wear out. That is the point." } },
  },
  [54] = {
    start = { title = "Dire Straits", { "Ah! A customer! Well, a donor. Well, a potential donor. The very best kind, because potential is a thing gnomes understand!" }, { "We exiles are in a spot, and there's no dressing it up. Short on cloth, short on room, short on everything except ideas, and you can't wrap a bandage round an idea. Believe me, I've tried. It came out as a schematic." }, { "Bring me cloth, any cloth, and the gnomes will think well of you. All of us, everywhere. That's not a small thing. Gnomes are everywhere, and we have long memories, and we write everything down." } },
    friendly = { title = "What We Left", { "Want to know what all this cloth is for, eh?" }, { "When we came out of Gnomeregan, we came out in a hurry. Nobody packed. You don't pack when the city's full of troggs and the air's gone bad. Half of us left in whatever we were wearing, and a good many of us were in nightshirts, or so the story goes, and nobody thinks to invent a faster pair of trousers until they need one." }, { "So the cloth goes to clothes, first. Then to blankets, because the cold up here never stops. Then to bandages, because the ones who go back to fight at the gates come home needing them. Then, when there's any left, to curtains. A gnome likes curtains. It makes a corner feel like a home." }, { "We're getting there. Corner by corner." } },
    honored = { title = "The Addresses", { "I keep a list. Don't laugh. Well, laugh a little." }, { "It's every address in Gnomeregan. Every street, every level, every workshop and flat and storeroom, and whose they were. I wrote it down from memory the first winter, and then I went round the exiles one by one and asked them where they'd lived, and wrote that down too. Some of them cried. Some of them corrected me. One of them corrected me and cried." }, { "Whoever walks those streets again, whenever that is, won't have to stand wondering which door was theirs. I'll have it written down. They'll go in the right door and find whatever's left, and it'll be theirs." }, { "That's what all this is for, really. The cloth keeps us alive till then. The list keeps us us. I keep it in a box lined with the first bolt anyone ever gave me here." } },
    revered = { title = "The Workshop", { "My workshop was on a lower level, past the big gears. Nothing grand. A bench, a lamp, a shelf of parts I was sure I'd need one day and never did. They're probably still there, being unnecessary in the dark." }, { "There was something on the bench when we left. Half done. I'd been working on it for a year, and it was going to be the best thing I ever made, and I can't tell you what it was, because I've forgotten. I've tried and tried, and I remember the bench and the lamp, and the thing on it is just a shape." }, { "That's the part nobody warns you about. You think you'll lose the city all at once, the day you leave. You don't. You lose it a little at a time, after, in your head. That's why the list matters so much to me, and why I'll keep a gnome's curtain on it as carefully as a gnome's door." } },
    aside = { title = "Corner by Corner", { "You know we've taken in enough cloth to curtain a whole street? I've started curtaining one. Just the one, for now, eh?" } },
    exalted = { title = "The Banner", { "Come here. Mind the needle." }, { "This is a banner. Or it will be, when it's done. It's for whatever day we next have something worth celebrating, because on a day like that somebody ought to be carrying something soft at the front, and I've decided it's going to be me." }, { "It's made of scraps. One from everything that's been donated at this table, since the first winter. Wool and silk and mageweave and runecloth, all stitched together. That patch there came from a gnome who walked out of the city with nothing else. That one's a sleeve off somebody's best coat. Most of the border came from folk who've never set foot in Gnomeregan. I didn't plan it that way. It just kept happening. Every stitch I've done at night, after the desk closes, with the lamp turned low. It's the best thing I've made since the workshop, and this one I'm not going to forget." }, { "I haven't got a joke for this. I've tried. I keep starting one and then stopping, because it's only true. The cloth at this table helped us stay alive long enough to have something to celebrate. When that day comes, you'll be out in the wind with the rest of us." }, { "There. That's the banner. Now help me thread this, my hands aren't what they were." } },
  },
  [76] = {
    start = { title = "For the Horde", { "You. Got cloth? Then you've got something the Horde needs." }, { "Orgrimmar fights on every front there is. The Barrens, the forest to the north, the hills over the sea. Every grunt who goes out needs wrapping before the fight and binding after. Steel comes from the smiths. Cloth comes from folk like you, or it doesn't come." }, { "Hand it over and the grunts won't know your name. Doesn't matter. They'll know they were warm, and dry, and bound up right, and that's more than most generals ever gave them." } },
    friendly = { title = "Shade", { "Get in the shade a moment." }, { "Durotar's a hard land. The sun bites and the sand gets into everything. Nobody else wanted it. Suits me. After long enough being told where to live, I'll take a place nobody can take off me." }, { "Somebody's wool went up as an awning in the Valley of Trials. I went down when they raised it. The young ones were drilling with axes, hours of it. The drill master called a halt. Every last one of them went under the awning at once, dropped where they stood, and slept in a heap, axes and all." }, { "Shade's no glory. Never was. A young one who gets to rest learns faster. A grunt who gets out of the sun fights longer. I've known both kinds." }, { "That was your wool, by the way.", after = 7826 } },
    honored = { title = "The Camps", { "You've earned a story. It's not a happy one." }, { "After the war, when the humans won, they put us in camps. Whole clans, behind walls, with guards on the walls and nothing to do. Day after day of nothing. You'd be surprised what nothing does to an orc. We stopped fighting each other. Then we stopped talking. Then a lot of us stopped wanting anything at all. We wore what they gave us. Sacking. Their cast-offs. Years of it, and I never once chose a thing I put on." }, { "Then the young Warchief came and broke us out, and we came across the sea to this land. The first thing I did, before I'd laid a stone, was trade for a length of cloth and make something to wear that was mine." }, { "That's why I took this desk. Every piece that crosses it is a choice the camps didn't let us make. Sounds like a lot to hang on some wool. It is." } },
    revered = { title = "The Young Ones", { "There are orcs in this city now who were born free. They've never seen a camp. Never worn sacking. They don't know what a guard on a wall means, except as one of ours, keeping them safe." }, { "Every one of them gets a proper cloak from me when they leave the Valley. Red, if I've got it. They take it without thinking, the way you take a thing you've always been owed. Then they run off to their first fight and don't turn round." }, { "That's the best thing I know. A young orc who doesn't know what this desk is for. The camps are a story to them. I want it to stay a story." }, { "You're part of that. Whatever you are, wherever you were born, you've put cloaks on orcs who'll never know your name. A few of the young ones come back to the desk years later, with a scar or two and a cloak gone brown, and ask for another. I give it to them without a word.", after = 7826 } },
    aside = { title = "Fronts", { "I keep one red cloak back in the storeroom now. Nobody touches it. Don't ask who it's for." } },
    exalted = { title = "The Rag", { "I cut up the rag last night." }, { "The one I wore in the camp. What was left of it. I'd kept it all these years at the bottom of a chest. Thought if I let it go, I'd forget, and if I forgot, it could happen again." }, { "I didn't burn it. I thought about it, most of the night. Burning's what you do to a thing you're afraid of, and I'm not afraid of it any more. So I cut it into strips and sewed them into the hem of the next red cloak, on the inside, where nobody'll find them unless they unpick it, and nobody unpicks a good cloak." }, { "Some young orc will wear the camps against the backs of her knees and never know it. That's the right place for them. Underneath. Behind. Carrying a free orc into her first fight." }, { "I couldn't have done it with an empty storeroom. You don't cut up your last scrap of anything. The storeroom's full because strangers kept it full. When there's enough, you can let a thing go." }, { "She gets the cloak tomorrow. She'll take it without thinking, and run." } },
  },
  [81] = {
    start = { title = "Brother, Sister", { "Hail, $gbrother:sister;. Walk with me a moment, if the wind allows it." }, { "My people have walked a long way to stand on these bluffs, and the walking was not easy. Now that we have stopped, we find we need things we never needed on the road. Cloth is one of them. We are short of it, badly, and I am the one who must ask." }, { "I do not ask easily. You will forgive me if I am slow about it. If you have cloth to spare, the tauren would take it gratefully. A kindness to one of us is owed by all of us, for as long as the bluffs stand." } },
    friendly = { title = "Hides", { "Every gift at this desk matters more than you might think." }, { "For as long as the oldest songs remember, we followed the herds. We wore hides, and slept under hides, and carried our lives on our backs and on the kodo. Hide is good on the road. It is strong and it is ours. But you do not weave hide, and you do not wrap a fever in it, and a child outgrows a hide coat in a season when a hide takes a season to cure." }, { "Now we live in one place, and the needs of one place are new to us. Blankets that can be washed. Bandages for the wounded who come back from the Barrens. Cloth for the lodges, so the wind does not find every crack." }, { "We are learning. The cloth that comes to this desk helps us learn faster than pride would let us." } },
    honored = { title = "Staying", { "My grandmother kept her pack by the door of the lodge until the day she died." }, { "She came to the bluffs with the rest of us, and she agreed to stay, and she meant it. But every night before she slept, she checked the pack. Every morning she stood at the edge of the rise and faced the horizon, as if the herds might call her and she would need to be ready." }, { "We never asked her to unpack it. You do not ask that of someone who walked this land from end to end more times than she could tell. When she died, the pack was still by the door, still ready. My mother emptied it. It took her a whole day, because she kept stopping." }, { "Staying cost my grandmother something every morning. It costs all of us a little. When I hand cloth to the lodges, I think of that pack, and I am glad of every warm thing that makes the staying easier." } },
    revered = { title = "The Earth Mother's Gifts", { "We believe everything comes from the Earth Mother. The grass the herds eat, the herds themselves, the hides we wore, the flax we are learning to grow. A gift, always. Given freely, and repaid in care." }, { "So when I take cloth from anyone, I take it as a gift that passed through their hands from hers. The sheep that grew the wool, the spider that spun the silk, the hands that wove it, and the hands that carried it here. That is a great many hands. I try to honour each of them." }, { "I have come to think that this desk is a small prayer. A small one. The shamans make the grand ones, and say them better. They usually do. This is only a tauren standing in one place, taking what is given and passing it on to those who need it, the way the land does. When the shamans pray, the sky listens. When I pray, a child gets a blanket. I would not trade." }, { "You have been a large part of that prayer, whether you meant to pray or not.", after = 7820 } },
    aside = { title = "The Wind's Share", { "When the wind blows hard up on the rises, the lodges creak, and the old ones say it is asking for more cloth. I have told the wind it can wait its turn." } },
    exalted = { title = "Asking", { "My grandfather would not have asked anyone for anything." }, { "He was a great hunter and a proud one, and he believed that a tauren who needs help has failed somewhere. He died on the road, the way he wanted, and he never held out his hand to a stranger in his life. He gave me this name, Proudstrider. I loved him. I was proud of him." }, { "I think he was wrong." }, { "I have asked strangers for cloth every day for years now. At first it shamed me. I asked quietly, and badly, and mumbled my thanks into my chest. Then the givers kept giving, generously, without wanting anything back, and somewhere along the way the shame went out of it. Asking became a kind of trust. You trust the one you ask, and they trust you to use the gift well." }, { "I have a daughter. She is small yet, and proud already, like him. So I will ask you something of my own. One day, when she is grown and has to ask a stranger for help and does not know how, be one of the strangers she asks. Answer her the way the strangers answered me." } },
  },
  [68] = {
    start = { title = "In Your Best Interest", { "Pay attention." }, { "The Forsaken need cloth. Wool, silk, whatever you happen to be carrying. Leave it with the clerks. They will weigh it, and enter it in a ledger that nobody reads but me, and I read it every night, line by line." }, { "Nothing left at this desk goes unrecorded. Nothing given here goes unnoticed. Most people find that reassuring. Some find it a threat. Both are correct, and I leave you to decide which you are." } },
    friendly = { title = "Why the Dead Need Binding", { "Cloth keeps coming to this desk. Very well. You ought to know what it is for." }, { "The living heal. They cut themselves, and in a week there is a scar, and they forget. We heal slowly and badly, and never all the way. The apothecaries can stitch and salve and slow the rot, but what the body loses, it is slow to give back. So we bind it. We wrap what is loose, and hold what is open, and keep ourselves together with cloth, the way you would keep a cracked jar together with cord." }, { "A Forsaken soldier goes through bandages faster than any of the living, and he uses them to hold himself together." }, { "The clerks find the question of why the dead need so much linen tiresome. So do I. The ledger has a page for nuisances." } },
    honored = { title = "The Merchant", { "Before, I sold silk." }, { "In Lordaeron. The city above us, when it was a city. I had a shop off the square, and the court bought from me, and I knew the weight of every bolt I sold and the name of every lady who wore it. I was good at it. I was proud of being good at it. That, I am told, is a very living thing to be." }, { "Then the plague came, and then the rest. I came to myself in the ruins above, with the same hands and none of the same customers, and later came down here. The first thing they gave me to do was count bandages. The coarsest wool, for holding dead soldiers together." }, { "I could have refused. I knew some who did, in those first years. I did not. It turned out a merchant who knows cloth is useful to the dead as well. The irony is instructive." } },
    revered = { title = "The Living", { "Most of what comes across this desk comes from the dead. We look after our own. But some of it comes from the living. Orcs, trolls, tauren." }, { "They carry something in with them that they do not notice. Warmth, truly, off their hands and their breath, and on the cloth for a little while after they set it down. I can feel it, if I am quick. It fades in a minute or two. Forsaken hands carry nothing of the kind. I have checked my own. Trolls run cool, orcs run hot, and the tauren warmest of all." }, { "I used to be warm. I remember it the way you might remember a language you spoke as a child. I could not hold a conversation in it now. But I know it when I hear it." }, { "Your cloth is the only cloth I check twice, whatever it carries. I do not tell the other clerks that I wait, after you leave, before I put it away.", after = 7813 } },
    aside = { title = "Inventory", { "I have instructed the clerks to stop weighing the cloth. They were only confirming what I already knew." } },
    exalted = { title = "What the Apothecaries Get Wrong", { "The first time you stood at this desk, I said that nothing given here goes unnoticed. I meant it as a threat as much as a promise. These days, it is only a promise." }, { "The apothecaries will tell you the dead feel nothing. They have studied it. They have papers. They will tell you that what we call feeling is a habit of the body, a twitch left over from life, and that it fades, and that a sensible Forsaken lets it fade." }, { "The apothecaries are wrong about a great many things. They are wrong about this." }, { "I felt something at this desk long before it had a name. Something like gratitude, which I had thought was among the things I lost on the way down here. It had only been waiting for a reason, and the reasons kept arriving, arms full, from strangers." }, { "I have stopped telling the apothecaries it does not exist. They have entered me in their own ledger, I expect, under curiosities. I can live with that, in the manner of speaking that applies to me. Someone has to be the exception in their ledger. It may as well be someone who keeps good records." } },
  },
  [530] = {
    start = { title = "The Weave", { "Come, come. Bring that here, let Vehena have a feel of it." }, { "Every piece of cloth got a story in it, ya know. Where the sheep grazed, what the spider ate, who carried it and how far. Most folk can't hear it. Vehena can. A gift from the loa, my grandmother said, or a curse, depending on the cloth." }, { "The Darkspear need cloth. Bandages, wraps, sails, blankets for the little ones down at Sen'jin Village, on the coast. Bring me some, and I'll tell you where you been. Free of charge. The loa don't like it when I charge." } },
    friendly = { title = "Where You Been", { "Ah, now. Let me read you. No cloth in your hands? Then I'll read the hands. They been on a long road. There's dust on them from a hot place, and something colder under that, from before. You been fighting, too. The hands remember." }, { "Vehena knows things." }, { "A fisherman down at the village lost his sail in a squall last month. The first wool through my hands after went down the road to him, and his daughter stitched it on, and now there's a boat going out every morning under a stranger's gift. We Darkspear are sea folk now. A boat without a sail is a troll without a supper." }, { "That was your wool, as it happens. The boat goes out under a sail that smells faintly of you. The village thanks you. The loa, they're always grateful, but with the loa it always costs something.", after = 7833 } },
    honored = { title = "The Isles", { "Off the coast, past Sen'jin Village, lie the Echo Isles. That was meant to be our home in this land." }, { "A witch doctor went bad out there. Zalazane. He took the isles for himself, and he took trolls with them, our own, hexed so deep they don't know their names. They walk his beaches with empty faces and do what he says." }, { "Now and then one of them comes back to us. How, I couldn't tell you. My grandmother said the hex wears thin with distance, like a rope. They come to the village with nothing. Not even their own minds, at first. We wrap them up. We bring them to the fire. We say their names to them till they say them back." }, { "A good deal of what comes to this desk goes to that. Blankets for trolls who didn't know they were cold. The first warm night, most of them sleep through to noon, and nobody in the village wakes them." } },
    revered = { title = "The Loa", { "The loa notice everything, ya know. Every gift. Every theft." }, { "The way my grandmother taught it, you bargain with them. A little smoke, a little of what you love best, and the loa give back what they please. The Darkspear brought the old loa across the sea with us, and they came, and they're here, in the smoke of the village fires." }, { "The gifts at this desk, they notice. Vehena knows, because the fires burn easier on the nights after cloth comes in. Maybe that's the loa. Maybe that's just more blankets, so more trolls sleep warm and nobody has to stay up feeding the fire. Both is true, I think. The loa like it when both is true." }, { "I made a bargain myself, when I was young. A little of what I loved best, for a little luck. I gave them my singing voice. Never got it back. The luck, I'm still waiting on. Maybe it came wrapped in somebody's wool, and I didn't notice." } },
    aside = { title = "A Long Road", { "So much road in every armful that reaches this table, Vehena could map the world off it. Yours too, one day. I'll leave out the embarrassing parts." } },
    exalted = { title = "The Trick", { "I can't read cloth." }, { "Never could. Not a thread. No loa ever gave me that gift, and I asked. It's a trick. You hold the cloth, you feel the weight, you smell it, you study the stranger holding it out, and you say something about a long road and a cold place and fighting. Everybody's been on a long road. Everybody's been cold. Everybody's been fighting. They nod, and they're surprised, and then they talk, and that's what I wanted. Folk who talk give more." }, { "I been doing it so long I half believed it myself. Some nights I still do." }, { "But somewhere back there, with you, I stopped. I don't know when. I just noticed one day I was talking plain and the patter was gone, and I didn't miss it." }, { "So from now on, I'll keep the trick for the village. They like it, and it does them good, and there's no harm in it. Anybody who asks me straight, I'll answer straight. And when a stranger comes up with an armful of wool and that look on their face, I'll think of you, and I might just say thank you and leave the reading out of it." } },
  },
  [21] = {
    start = { title = "Quiet Guests", { "Booty Bay, partner. Everyone is partner here until they prove otherwise." }, { "Have a drink. Spend some money. I ask one thing of a guest, and it is that nothing happens while they are here. Nothing at all. My bouncers are very good at seeing to it, and they get a little extra when they have to." }, { "You are nobody to me yet, and I mean that kindly. Most people in this bay are nobody to me. The ones who matter are the ones who do something for the Steamwheedle Cartel, and for the goblin who runs its port. Do something, and we will talk again." } },
    friendly = { title = "What the Bay Is For", { "So. Word reached me that you have been doing things for the Cartel. Now you can know what this bay is for." }, { "Booty Bay has a fleet of its own, and the fleet is mine. The Blackwater Raiders sail out of this harbour, and my fleet master keeps the lanes open for anyone who pays the Cartel. Out past the point, a fleet under red sails would like those lanes for itself, and I take that personally. So should anyone drinking my liquor." }, { "Inland, the Venture Company is stripping the jungle for timber and ore. They are goblins too, and that has never settled whose side a goblin is on. I have never cared for a goblin who digs where I can hear him." }, { "Keep doing things, and the bay will start to make room for you." } },
    honored = { title = "The Collection", { "Come in. Touch nothing." }, { "I collect. Troll things, mostly, from the empire that held this jungle long before anyone thought to put a port in it. Masks, idols, blades nobody can lift. The Gurubashi made beautiful things for terrible reasons, and I have never minded the reasons." }, { "There was one piece I wanted more than all the rest. The Stone of the Tides. I first read of it in an old book of troll legends: a stone that holds a tide, and a curse on whoever carries it, who fades out of the world and back again. A goblin wizard named Gazban was said to have found it. Gazban turned out to be real, and the curse with him." }, { "It stands on its own pedestal now, and the tide in it never stops moving. You brought it to me, and Gazban is quiet at last. Nobody else has touched it since, and nobody will.", after = 611 } },
    revered = { title = "Ears", { "Krazek listens for me. He keeps to the tavern and hears every rumour that comes ashore, the strange ones especially, and brings them up the stairs. So do others whose names you will never learn. Krazek has a good ear and a poor memory for faces. For his work, that is the right way round. Most of what is said in my bay reaches me before the people saying it have finished their drinks." }, { "That is how a baron stays a baron. Those who cross me do not get to discuss it afterwards, because I hear about it first. Lonely is what visitors imagine. Mostly it is a matter of knowing what is coming up the stairs." }, { "Your name has come up those stairs a good deal, from this bay and from the Cartel's other towns, which tell me more than they admit. I listened to all of it. I have had people watched for less than that, and rewarded for less, and I have never once been unsure which a man deserved. With you, for a while, I was." } },
    exalted = { title = "The Stairs", { "Krazek came up the stairs this morning with your name, and I sent him down again. He took it badly. Listening is the only thing he has ever been praised for." }, { "I told him I would not be needing it, about you. Of all the people who come and go in this bay, you are the one I have stopped listening for. It took me a long time to manage it, and I am still not sure I like how it feels." }, { "That first day, I asked you for one thing, that nothing happen while you were here. I take it back. You have been the most eventful guest this bay has had in years, and every event went my way. Cause all the trouble you like." }, { "The red sails are still out past the point, the Venture Company still digs where I can hear it, and there will always be someone on the stairs who thinks the top floor would suit them better. That is the bay, and I would not change it. It is a little easier to run with one person in it I trust without checking." } },
  },
  [369] = {
    start = { title = "Price of Water", { "You there! Thirsty? Of course you are. This is Tanaris." }, { "Chief Engineer, Gadgetzan Water Company. I keep the wells pumping, the pumps powered and the price fair. Fair for the Company, I mean. Every single thing in Gadgetzan costs something, water most of all, and if you came for sympathy instead of water, there is a whole desert of it outside the gate." }, { "The nomads out there will tell you water ought to be free. The nomads also took our wells, and killed the people who kept them." } },
    friendly = { title = "Justice", { "Now you are someone the Company can talk to!" }, { "The situation is this. The Wastewander nomads have taken nearly every well in this desert. Our wells. We dug them, we powered them, we sent our people out to keep them running, and the nomads killed those people and kept the water. Some would call that a dispute about business. The Company calls it theft with a body count." }, { "Their leader is called Caliph Scorpidsting. The Company has had his face drawn on a poster and a price written under it, and the price is a good one." }, { "Whatever you have done for the Company, the Company noticed, and it does not forget who helped. One day those wells come back to us. I intend to be standing at the first one with a wrench." } },
    honored = { title = "The Rod", { "Want to know how a goblin finds water in a sea of sand? Engineering! Also, a stick." }, { "The divino-matic rod. You walk the dunes with it, and when there is water far underneath, it knows, and you dig, and the Company has a new well. Every new hole I have dug started with that rod in my hands. I would sooner lose a hand." }, { "Then Sergeant Bly asked to borrow it. Borrow! He took it treasure hunting among the trolls of Zul'Farrak, with a band of adventurers of the worst sort, and he never brought it back. A man who steals a goblin's gold is a thief. A man who steals a goblin's divining rod in a drought is something I am not allowed to say in front of customers." }, { "It has been finding water again since it came home. The Company has stopped asking me where the new holes come from, and I have stopped explaining.", after = 2768 } },
    revered = { title = "Snow", { "The Company has a long plan, and I am the only one who has drawn it." }, { "Dun Morogh! Up north, the dwarves have springs so cold the water hurts your teeth. More water than they know what to do with. Ice falls out of their sky, for free, all winter long! One day we pipe it, or ship it, or cut it into blocks and haul it across the sea, and Gadgetzan is never thirsty again. Nobody fights over a bucket. Nobody gets killed at a well. I can stop selling power sources to people who drop them in the sand." }, { "Until then, I sell water, and power, and patience, and I charge for all three. The money is going somewhere, is the point. I have a drawer full of drawings for it, and one drawing of a tree that grows power sources. The Company has asked me to stop bringing that one to meetings." }, { "I would like to live long enough to be bored by water. Imagine that. A goblin in Tanaris, bored by water." } },
    exalted = { title = "On the House", { "Hold out your hands." }, { "That is a cup of water. Cold and clean, from the deep well, the good one. It is free. I have practised saying that. It still sounds strange." }, { "Do not make that face. I know what I said the first day, and I meant it, and I still mean it for everybody else. In Gadgetzan everything costs something. But the Company owes you, and the Company pays what it owes, and today I am the Company, and I say this one is on the house." }, { "Whatever you did for this town, you did it for a place that charged you for every sip, and you kept doing it. You put up with me. My own engineers would tell you that is the hard part." }, { "And then there is the caliph. The Company paid the bounty for him, and I added nothing to it, because the Company's money is the Company's. This cup is mine.", after = 2781 }, { "Drink it slowly. It tastes better when nobody is charging you for it. Tell nobody. Word that the Chief Engineer gave water away would have a line round the block by noon, and I would deny everything." } },
  },
  [470] = {
    start = { title = "The Docks", { "Gazlowe. I run Ratchet. Ships come in, ships go out, goods change hands, I take a little off the top, and everybody goes home happy. That is the theory." }, { "The practice is pirates. The Southsea Freebooters hit my ships up and down this coast, and lately they have pitched their tents within a short walk of my docks. The trade princes have sunk a fortune into the fleets that are meant to stop them, and I am still short a lens, a crate of boots and a good night's sleep." } },
    friendly = { title = "The Payroll", { "Kid! You are starting to turn up in my ledgers on the right side." }, { "Ratchet works like this. Everybody who matters is on the payroll. The wharfmaster, the bruisers, the fellow who checks on the bruisers. Dizzywig keeps the dock logs, and I trust his logs because I pay him." }, { "Then there are the people you cannot pay. Pirates, mostly. And the vice admiral whose whole job is keeping these waters clear, and who could not clear a bathtub. Every time a Freebooter sails past Grezzlik's fleet with my cargo aboard, I write it down. I have a whole book of Grezzlik." }, { "Whatever you have been doing for the Cartel, you have not been doing it for my money. I pay too badly for that. I am still working out what you are doing it for." } },
    honored = { title = "The Heedless", { "The Heedless passed me once at sea, years back. What a hull. Long and low and quick, built, I would swear, by someone who loved boats more than money. I know the sickness. I still have a sketch of her lines somewhere." }, { "Her captain was Baron Longshore, out of Gilneas, and he used that beautiful ship to trouble mine for the Southsea. I put his name on a wanted poster and meant every word of it. I also hoped, a little, that whoever took him down would leave the ship in one piece. You can want a man gone and still want his boat." }, { "That is how it goes with pirates. They steal from you with the best shipwrights' work on the sea, and you hate them for it, and you take notes." }, { "He will not be troubling anybody now. I paid the bounty gladly. I never asked what became of the Heedless. Some things a goblin does not want an invoice for.", after = 895 } },
    revered = { title = "No Money In It", { "That is my observatory, up there on the hill. Do not ask what it earns." }, { "A caravan brought me the first lens from Durotar. A ship was meant to bring me the second, and the pirates got the ship. I nearly gave up on the whole thing." }, { "Then you went into their camp and came out with it, and now on a clear night the sky comes right down to Ratchet.", after = 888 }, { "People ask what a goblin wants with the stars. There is no money in them. That is the entire appeal." }, { "Same with Pozzik's racing team. I find parts for them in every port I have, and once I got my own hands black working on one of the rigs, and I have not been that happy on a dock since. No profit in it. None. The gnomes are still closing the gap, and I keep sending parts." }, { "Everything else I own makes money. Those two things just make me glad to get up in the morning. Undermine would want a cut of that too." } },
    exalted = { title = "What I Built", { "I have built a lot of things in my life, kid." }, { "A city, once, for an orc warchief who paid on time. You would be surprised how seldom that happens. This port, plank by plank. An observatory nobody asked for. Fuel lines for racers that may never win. I can tell you what went into every one of them, down to the last nail." }, { "The trouble is this. I have the money for one more, and two drawings on the table. A breakwater out past the docks, to keep the Southsea from sailing right up to my warehouses. Or a proper lighthouse on the point, so nobody honest ever runs aground coming in at night. The breakwater is sensible. The lighthouse is beautiful. I have gone back and forth for a month and lost every time." }, { "So I am asking you. You have done more for this Cartel than most goblins who were born into it, and you have no money riding on it either way. Pick one. I will build it, and when anybody asks why that one, I will tell them whose idea it was." }, { "Take your time. Not too much. Lumber is not getting any cheaper." } },
  },
  [577] = {
    start = { title = "New in Town", { "Oh! Hello! You are new. Everybody in Everlook is new for about a day, and after that they are just cold, like the rest of us." }, { "I am Umi. I live here. A gnome in a goblin trading post, up where all the roads of Winterspring cross, with nothing outside the walls but snow and things that want to eat you. I like it. Things get built here, and traded, and argued over." }, { "My friends are clever. Every one of them always has some marvellous scheme going, and they never let me forget it. One day I am going to have a better one. I have not decided what yet." } },
    friendly = { title = "Word Gets Around", { "Did you know the goblins up here talk about people in other towns? All the time!" }, { "That is how the Cartel works. There are four goblin towns, the bay, Gadgetzan, Ratchet and us. They are very far apart and they gossip like neighbours. Help one of them and the others hear about it by the next caravan. Suddenly the goblins up here are friendlier to you than they have ever been to me, and I have lived here for ages!" }, { "I do not mind. Well, a little. It is nice, though, being friends with somebody the whole town likes. Legacki asked me about you just yesterday. I said you were very nice and very brave and terribly good at keeping secrets." }, { "Which reminds me. Can you keep a secret?" } },
    honored = { title = "The Plan", { "Promise you will not tell anyone. Promise!" }, { "I am going to build a yeti. A mechanical one, with real ice thistle fur and the biggest horns, the handsome unbroken ones, and gears inside, and it is going to walk right up to my friends and scare them half to death. Legacki here, Sprinkle out in the desert, and Quixxil in the crater. All three. And then, when they have stopped screaming, they will look at it properly and see how well it is made, and they will be impressed." }, { "That is the important part. The screaming is just for fun. The impressed is what I want." }, { "Is it silly? It is a little silly. Engineering usually is, at the start." }, { "And you did it! You carried my yeti to every one of them. Legacki dropped a whole tray. Sprinkle still will not talk to me. I think that means it worked.", after = 5163 } },
    revered = { title = "Why It Mattered", { "When my friends come up with a scheme, everybody listens. When I come up with one, they laugh first and listen after, when they listen at all. They are not mean about it. That is almost worse. They just think it is funny that the gnome has ideas too." }, { "The yeti was my answer. I spent a long winter making something they could not laugh at, every coil of it, every bolt in its jaw. I wanted them to stop laughing so badly that I forgot to enjoy it for a while." }, { "I have been asking myself who I build for. The ones who laugh, or the ones who ask. Legacki says I am overthinking a yeti. Legacki has never built anything that walks. I have not worked out the answer yet. I am closer, though." }, { "You helped me, and you never laughed once. You asked how it worked. You were careful with the horns. I kept thinking about that more than about whether they screamed.", after = 5163 } },
    exalted = { title = "You First", { "I have a new idea. A good one. It is drawn out on the bench, and it is the cleverest thing I have ever thought of, and nobody in the whole world knows about it yet except me. And now you." }, { "The surprise is that I am showing it to you before I show my friends. I always used to rush to them first, all breathless, waiting to find out whether they would laugh. I do not want to do that any more. I want to show it to someone who will ask how it works." }, { "People ask why a gnome lives at the top of the world. The truth is that the cold keeps everyone indoors, talking, and I love the talk, even when it is about me. Lately it has been about you, and I have stopped minding that the goblins like you so much. Some days I think they have better taste than I gave them credit for." }, { "And you can build a yeti of your own now! Go and frighten someone for me. Somebody who deserves it.", after = 8798 }, { "So. Tell me what you think. And if it is a silly idea, tell me that too. I trust you to." } },
  },
  [909] = {
    start = { title = "Step Right Up", { "Come in, come in, come in, there is room for everyone and wonder to spare!" }, { "The Darkmoon Faire has crossed the whole of this marvellous world to set up its tents in your field. Beasts from the edges of the map. A strongwoman who lifts what cannot be lifted. A man who remembers everything you have ever told him, and a fortune teller who knows what you have not told anyone." }, { "Buy a ticket, eat something fried, lose a little money at the games and win it back at the next. Nobody leaves the Faire the way they came in. That is a promise, and Silas Darkmoon keeps his promises, most of them." } },
    friendly = { title = "The Folk", { "Back again! Splendid. Allow me to introduce the family." }, { "That is Chronos, who never forgets, and who will tell you so whether you ask or not. Yebb keeps the menagerie, where nothing is quite what the sign says and everything is better. Kerri Hicks will bend an iron bar for you. Rinling took a blood oath to make every guest smile, so smile at Rinling, I beg you, for Rinling's sake." }, { "And every one of them needs something. Leather, hammered steel, little whirring gizmos, the pelts of things with teeth, and those strange cards that turn up in the world and want to be a deck. A fair is a hungry creature. It eats what the world makes, and turns it into tickets, and the tickets into prizes, and the prizes into stories you will tell your children." }, { "You have fed it well. The family has noticed." } },
    honored = { title = "The Road", { "Tonight we are here. By the next moon we will be gone." }, { "That is how the Faire lives. We set up in the grass of Elwynn, under the oaks, and play for the farmers and the soldiers and the children who ran away from their chores. Then we fold every tent, pack every crate, coax every beast into its wagon, and roll off to Mulgore, where the tauren come down from the bluffs to find out what the noise is about." }, { "A fair that stays in one place becomes a market, and a market is a dull thing. We never stay. Some of my folk were born on the road and have never spent a whole season in one field. They would not know what to do with a roof." }, { "The wagons know the way better than I do by now. Elwynn, then Mulgore, then Elwynn again, and every time we come back, the same children are a little taller and pretend they have outgrown us." } },
    revered = { title = "Sayge", { "Has Sayge read your fortune yet? Of course she has. Sayge reads everybody's." }, { "Sayge says a fortune is only what you were going to do anyway, said out loud. I think she is right. I also think it is the most frightening thing I have ever heard said in a tent, and I have heard a great many things said in tents. Her tent is the quietest on the grounds. People go in laughing and come out thinking, and the next night some of them bring a better question." }, { "She has never read mine. All my years on the road, and I have not answered a single one of her questions. A showman should not know how the show ends. He might start playing to the ending instead of to the crowd." }, { "I chose the road. Nobody made me. I could have had a house and a garden and a sensible trade, and I chose a wagon and a painted sign. Every morning I choose it again. Some mornings it rains on the wagon, and I choose it anyway. Those are the mornings that count." } },
    exalted = { title = "After the Lights", { "Stay a little. The last of the crowd has gone home." }, { "This is the part no ticket buys, and it is the best show I have. Listen. The lanterns come down one by one. Kerri lifts her own weight bench into the wagon by herself, because she likes to. Chronos counts the takings and remembers every coin. Yebb sings to the beasts until they sleep. Rinling, off duty at last, leans on a wagon wheel and does not smile at anybody, and it is the most peaceful face in the whole Faire." }, { "Every night I tell them this is the finest show there is, and every night I mean the tents and the lights. This is the other one. The family, putting itself away, tired and quiet and pleased." }, { "I talk too much. You will have noticed. All the step right up and the marvel and the wonder, it is how I say thank you. I have never found another way, and I have been saying it to you for a long while now. So, once, without the drums: thank you." }, { "Now. There is a crate of tent pegs by the wagon, and nobody here stays a guest for ever." } },
  },
  [87] = {
    start = { title = "The Bay's Smell", { "Ye smell of the bay. Steamwheedle coin and goblin soap." }, { "Every soul who runs errands for Revilgaz is an enemy of the Bloodsail, and we've a long memory for enemies and no patience for them. I've known plenty start where ye stand, fetching for the goblins, till the day they set what the bay pays beside what the sea pays and did the sum." }, { "The sea's a wide place. The bay's the only thing on it that tells a Bloodsail where he may not sail. Some day ye may tire of the goblins. There's a red ship that takes on hands, and nobody aboard her asks where ye've been." } },
    friendly = { title = "The Two Throats", { "Well now. The bay's bruisers reach for their clubs when ye walk in. Good. That's the first honest welcome a goblin ever gave anybody." }, { "Ye bled the bay a long while to get here, and ye know what it cost. Every goblin town has yer name on a list by now, and it's not the list ye'd want." }, { "Ye wear the colours well. The man who had them before never filled them out, and the storm has him now.", after = 9272 }, { "The bay has two throats that matter. Fleet Master Seahorn, who keeps their ships on the water, and the Baron, who keeps their law on the land. Cut both, and the goblins learn there's a flag on this sea they can't buy." } },
    honored = { title = "Crew", { "Honored, is it. Precious few on this ship ever got so far with us, and most of them were born to the trade." }, { "I took ye on as a knife. A knife's a useful thing, and ye're careful with it, and ye come back. These days I'd trust ye with the wheel, and I don't let my own mother near the wheel." }, { "Ye did what I asked, both of them, and walked out of the bay to tell it. The hat suits ye, Admiral. There's not another like it on the sea. Every time ye cross the deck in it, the crew stands up straighter, and they've no idea they're doing it.", after = 4621 }, { "Some go back, ye know. Every few seasons one of mine gets homesick for clean sheets and goblin ale, and the bay takes them in again, for a price, and we call them traitors after. I don't blame them much. The sea's hard on folk." }, { "Before they go, I give them the same advice. A goblin's forgiveness costs coin. The sea's costs nothing, and it never once asked me to wipe my boots." } },
  },
  [349] = {
    start = { title = "The Path", { "Welcome, welcome, welcome! Nobody finds this house by accident, which means either we wanted you found, or my guards have grown careless, and I shall be finding out which before supper." }, { "Ravenholdt is a house of fine hands. Thieves, assassins, people who can take a ring off a finger and leave the finger none the wiser. We have quarrels, naturally. Alterac's leftovers have named themselves the Syndicate, hold their knives by the wrong end, and keep breeding more of themselves." }, { "You are not one of mine, and I could not say yet what you are. Show me, and do it quietly. Quiet is what I am always short of." } },
    friendly = { title = "Emblems", { "Ah! The Syndicate has been missing men in the hills, and their emblems with them. I can always tell." }, { "Every one of them wears an emblem, and every emblem lost is a small disgrace for the man who wore it. We seldom need the blade. A Syndicate man who has lost his emblem has already lost the thing that mattered, and what he faces among his own is no concern of mine. I count it the prettiest work this house has ever done." }, { "That is the whole of our art, you see. Subtlety first. Force when subtlety fails, and it fails less often than people who prefer force believe. Anyone can open a throat. Very few can open a purse in a crowded street and close it again." }, { "You have served this house, and the guards nod you through the gate now. That is how a welcome looks at Ravenholdt." } },
    honored = { title = "Locks", { "So you are one of the trade after all. I suspected as much from the way you stand." }, { "You have been bringing Fahrad boxes, I hear. Heavy, stubborn, ugly little boxes, and he sets the young ones on them because a lock is the most honest teacher in the world. It does not care who you are, or who your father was, or how much you would like it to open. It opens when your hands are right, and not one moment before. You leave a few coins in each, I am told, so the young ones have a reason to keep trying. Encouragement, Fahrad calls it. I call it bait, and I approve. They tell me I was a poor student at it once. I do not remember it that way." }, { "Patience and hands. Everything else we teach is decoration on those two. Most who come to this house have one. Very few have both, and the ones who do are the ones I keep in mind. I have been keeping you in mind for some time." } },
    revered = { title = "The Bag", { "I lost something once." }, { "A small blue bag. Its contents are my own affair, and will stay so. Thieves took it, so they were good. They could not open it, so they were not good enough. Then they found a buyer for a locked mystery, a shaman in Azshara who took it for a relic. A holy thing is whatever the customer needs it to be. Then the thieves died, as people who rob me do. I was left with a bag I could not reach, and a key that had gone somewhere worse, into the lair of a green drake in a sunken temple." }, { "It was the one lock I could never leave alone. I would wake in the night with my fingers already moving. I have wanted very few things in my life that way, and never one so small." }, { "The key came back with you. I opened it that same night, alone, the door locked, and what lay inside lit my hands. I stayed a long while with the light on them before I let anyone in.", after = 8236 } },
    exalted = { title = "The Pupil", { "There is nothing more I can teach you." }, { "It is the hardest sentence in my trade, and I have never once enjoyed saying it. A master is a master only as long as there is a pupil who needs him. You do not need me. Your hands are as good as mine, some days better, and your patience has outlasted every test this house could set. That is the best thing to happen to Ravenholdt in years, and I mean it, though it cost me something to get used to." }, { "So I will give you work instead. There is a girl in the yard, all elbows and nerve, who cannot open a junkbox to save her life. Teach her. She reminds me of someone, though I could not tell you who. Use your hands, not my words. Mine have stopped working on her, and I suspect yours will not need many." }, { "And wear what I gave you. The word has gone round this house and through the Syndicate's camps, and nobody has tested it. A pity, in a way.", after = 8236 }, { "I will be in the hall, listening for the click from the yard." } },
  },
  [471] = {
    start = { title = "The Aviary", { "Mind the roosts, and mind your head. A gryphon that doesn't know you will take it off and think nothing of it." }, { "This is Aerie Peak. We're no part of any Alliance, mind. Our doors are open to it and shut to the Horde, and that's the long and short of it." }, { "Our real trouble is closer to home. The Witherbark have these hills crawling with trolls, and every one of them would sooner have a gryphon on a spit than in the sky. Thin them out, and you'll find the aviary friendlier. The gryphons won't care either way. The riders will." } },
    friendly = { title = "The Best Rider", { "You've been busy in the hills. The riders talk." }, { "The best gryphon jockey I ever had was a chap called Rhapsody Shindigger. Nobody flew like him. I sent him south once to help a fellow of the Explorers' League, and he came home with a thirst on him that never went away." }, { "We all drink up here, and gladly. Rhapsody stopped being glad about it. I had to take him off the birds before he lost one to the drink, and I haven't forgiven the ale, or myself, or the League, though that last one's not fair. My father dug with them, on the team that found Uldaman. I've a weakness for anyone who goes looking for things." }, { "So when a new rider comes up to the roost, I hold them up against Rhapsody. Not one has measured up yet." } },
    honored = { title = "Sharpbeak", { "Swiftwing's son went missing a few days back. Sharpbeak. The finest young gryphon this roost has hatched in my time, the one we'd all decided would be leading it one day." }, { "He was out hunting with his parents and never came home. Trolls, we knew, but which trolls? The Witherbark cages were searched and turned up nothing. So was the Vilebranch altar, where they do worse than keep things in cages. That was the only good news in a bad week." }, { "To us a gryphon is half the rider and all of the clan's strength. Lose the best of the young ones and the whole roost goes quiet. You could hear it. Nobody sang at supper that night, and up here somebody always sings." }, { "You brought him home. His mother and father haven't stopped fussing over him since, and the first evening the three of them were back in the roost together, I had to go and stand behind a pillar for a while. The riders were decent enough to look at the sky.", after = 2994 } },
    revered = { title = "The One Who Left", { "Thadius Grimshade. Diviner. Lives at Nethergarde now, in the Blasted Lands, among mages and worse. He walked out of the peak a long time back, after knowledge of the darker sort, and plenty up here said good riddance. I never did." }, { "A dwarf can leave the roost and keep the roost in him. Thadius has. I'd bet my beard he keeps a gryphon feather on his desk among all those books. And I'd wager Rhapsody still turns his head when a gryphon flies over Quel'Danil. You don't stop being one of us by flying off, any more than a gryphon stops being a gryphon when the peak is out of reach." }, { "And when we needed him, Thadius found Sharpbeak for us with one feather and whatever dark arts he keeps at Nethergarde. He asked a price, a troll's medallion, and you paid it. That's Thadius. And he found him all the same.", after = 2993 }, { "I've been wondering lately how you'd do on a gryphon. I've a feeling you'd be good. Better than good. It would be a fine thing to find out one day, with the whole roost pretending not to care how it went." } },
    exalted = { title = "Up", { "My father spent his whole life digging down. Uldaman, and every hole the League ever asked him to poke his beard into. I spent mine going up. We used to argue about it over the ale, which way the truth was, under the stone or over the clouds. Neither of us won." }, { "He'd have liked you. You go looking, the way he did. You fight for what's ours, the way I'd want. The hills are quieter for you, the trolls thinner, and the riders tell stories about you at the roost, the good kind." }, { "Last week I went out to Quel'Danil to see Rhapsody. First time since I let him go. He was half in a barrel, as usual. I told him about you. He laughed and said it sounded like I'd found another one." }, { "I told him there'd never be another one. Then I told him it had taken me all these years, and you, to stop holding everyone up against him. He didn't say anything to that. He poured me a cup instead, and I drank it with him, and for once it was a good time for one." }, { "Fly well, wherever you go. The trolls are thinner. They aren't gone." } },
  },
  [92] = {
    start = { title = "Gelkis Earth", { "You stand on Gelkis earth, and it does not know you." }, { "I hear the earth. It tells me who walks on it, and how heavily, and what they carry in their hearts. You it cannot read yet, so there is no place for you at our fires." }, { "The Magram are our enemies. They are loud, and they believe their strength is enough. The earth is stronger than strength. When the earth knows your name, I will speak with you. Until then, go back the way you came." } },
    friendly = { title = "What the Earth Says", { "The earth is heavy with Magram now, and you are the one who made it heavy. This is good. Now we will talk." }, { "Listen. The Gelkis do not fight only with spears. We fight with what the ground gives us. We believe the mother of the centaur, Theradras, lies beneath this land, and that the earth is her voice. We keep her tears in our cave, and while we keep them, she keeps us." }, { "The Magram say nobody protects the centaur. They say it loudly, and they listen to nothing. So they will lose. A clan that listens to nothing has nothing to warn it when the ground shifts." }, { "You are not Gelkis. You never will be. But the earth no longer trembles when you climb to our village, and among my people, that is the first word of friendship." } },
    honored = { title = "Why You Came", { "The earth has told me a secret about you." }, { "Your people came to Desolace to learn how the centaur are beaten. You chose the Gelkis because we hate the Magram, and hate is a door. When the Magram are weak, your people will turn to the Gelkis, and they will already know how to break us. I knew it from the start. I let you come anyway." }, { "The earth does not lie, but it does not choose. I choose." }, { "A red crystal came into our earth not long ago, from a broken land far beyond this sky, a land of demons. It is new, and strange, and strong, and the earth does not yet know what it will do. You are like that crystal." }, { "Khan Jehn leaned on his strength as on a wall, and the earth is patient with walls. Your hands brought it down, for us.", after = 1374 }, { "When your people come to break the other clans, let them leave the Gelkis standing. That is all I ask of them. Of you, I ask nothing more. You are a friend. I say it knowing what I know." } },
  },
  [93] = {
    start = { title = "Strong", { "Go away. The Magram kill the weak, and I do not know yet what you are." }, { "The Gelkis pray to a mother under the ground. They think she keeps them. Nobody keeps the centaur! Nobody ever kept the centaur. We keep ourselves, with hooves and spears, and the Magram keep themselves best of all, because we are the strongest." }, { "You want to talk to Warug? Kill Gelkis. Then come back, and I will know what you are." } },
    friendly = { title = "Laughing", { "Ha! You killed many Gelkis. Their scouts spit your name now, the same spit they keep for us. Good!" }, { "You are not a centaur, but you fight a little like one. Do you laugh while you fight? You should. A warrior who laughs shows the enemy that the enemy is small, and the enemy believes it, and then he is small. That is how the Magram fight. The Gelkis sing to stones. We laugh, and we win." }, { "The Gelkis keep crystals in a cave and call them the tears of the mother. Tears! When they are broken, the mother does not come. She never comes. One day I will break every one of them, and the Gelkis will finally know what the Magram already know." }, { "Now we talk, you and Warug. Bring me something to laugh about." } },
    honored = { title = "The Little Wooden Man", { "Once a gnome no taller than a child came out of the dust behind his horses, with a cart of toys. Fires in colours. Little engines that went on without breath. He was the funniest thing I ever met. I killed him. He made me laugh first. I remember." }, { "I kept the toy I liked best. A wooden man with a hand that went up and down. Hello, hello, hello. One day I struck it, and it came apart in my fist. I was sorry. Warug is never sorry. I was sorry about the little wooden man." }, { "You brought me a new one. I made it move. It stands in my tent, and I do not hit it. I am strong enough not to.", after = 1371 }, { "Shaka is dead, by your hand. His head is on a pike by my door, where Shaka can learn what the Magram are.", after = 1375 }, { "You are strong, so I tell you. The Magram will rule Desolace, and the other clans will be under our hooves. I like you. I like loud things, and fights, and the little wooden man. Now I like you too." } },
  },
  [2778] = {
    start = { title = "The Empty Sky", { "Look up. Higher. You see the sprites drifting about the island and you think the winds still keep us company. They only wear the winds' shape. The spirits who carried my people into Skywall, who spoke with us and held this island up, have been silent a long time." }, { "The Windshapers have sworn to find where they went and fetch them back, whatever it costs and however far down the road goes. Walk it with us, or walk it somewhere my word does not follow." } },
    friendly = { title = "What We Owe", { "Now you are owed the truth of standing with the Windshapers." }, { "The spirits gave us their gifts, instruments and constructs both, and we tend them still. We read the wind, because the wind is the last of them that still moves. And we watch the land. It is opening, the ley lines rising through it. We call the wounds scars. The magisters of the High Order would sooner study a scar than ask what made it." }, { "We answer the Al'Aketh, every time. I soften that for no one." }, { "What you do for us pays part of a debt, and the debt is ours." }, { "The shrine fell and its priestess ran. Whatever shielded this island from the Windlord is gone now. I read the sky every night. So far it has only looked back.", after = 93836 } },
  },
  [2779] = {
    start = { title = "What We Forgot", { "You find us searching. An order of scholars that has lost most of what it knew does little else." }, { "We are alone now. The winds that carried my people into Skywall are gone, and I say so because most of the island still cannot. We were Highborne scholars once, and somewhere in the long years since, we forgot how to do anything the winds did not do for us. The High Order intends to remember." }, { "There is work here for anyone willing to look." } },
    friendly = { title = "Below Us", { "Some come to the High Order born to it, some by choice, and I have stopped asking which. What matters is what you will do with it." }, { "We look for what our ancestors knew before the winds made knowing unnecessary: the arcane of Eldre'Thalas, a strength that does not depend on anyone's kindness. An archmage of the Kirin Tor in Dalaran answers my letters. The winds have not, in a long time. Azeroth went on learning while we drifted. It will teach us, if we are humble enough to ask." }, { "The Windshapers think us reckless. You will hear them say so. Hear them out, then come back here and do the work anyway." }, { "I sent Belathaan to the shrine to talk. I was certain talk was possible. I have been certain of very little since, and I work better for it.", after = 92834 } },
  },
  [730] = {
    start = { title = "Recruits", { "Name, kin and trade, on the list. The clerk reads it later, or I do." }, { "I sign up soldiers for the Stormpike Guard, and I need a great many of them. The valley eats soldiers the way a forge eats coal. You go in, you fight, you come back out, or you don't, and I sign up the next one. That's the job. I'm good at it." }, { "Every soldier of the Guard wears an insignia, and the insignia grows with the soldier. Show me what you're made of on the field, and I'll see you get a better one. Lose it, and I'll find you another. I always have more." } },
    friendly = { title = "First Rank", { "Still standing, soldier? That's more than most can say." }, { "You'd be surprised how many never get this far. They come up the road full of songs, walk into the valley, and that's the last of them I see. Plenty never get further than a name on a list. You did." }, { "There. Pin that on. Rank, soldier, a better one than the last. Don't make a liar of it.", after = 7168 }, { "Nobody tells the new ones what the insignia's for. It's so the soldier next to you knows you've stood your ground before. That's all. A dwarf in a snowstorm with a Frostwolf coming at him wants to know whether the stranger at his shoulder will run. The insignia says you won't." }, { "I keep a rank here for every soldier who's earned one, and a better one after that." } },
    honored = { title = "The King's Ear", { "Word's gone up the mountain about you. All the way up." }, { "The base talks, and the base writes home, and some of what it writes, between the complaints about the soup, reaches the king himself. Your name did. I've sent a good many soldiers into that valley, and the king hears of very few of them." }, { "He wants that valley. He's made that clear to all of us, in letters with a great deal of seal on them. Every soldier I send in is a piece of what he wants, and most of them, I'm sorry to say, are worn out or gone before he ever learns what they were called." }, { "You come home whole, battle after battle, and you go back in. That's how a name gets up a mountain." }, { "Take the new insignia. The king knows your name now, so wear it where he'll hear of it.", after = 7169 } },
    revered = { title = "The Troll Who Would Not Stay Dead", { "There's a third side in that valley." }, { "The Winterax trolls. Cannibals, up in the caves, and dwarves would end up in their stew pots, given the chance. Their chief was a brute called Korrak. We killed him. Good. Then the trolls brought him back, the way trolls do. Burn the body, I always say, when a troll falls. Nobody burned this one." }, { "A war has more than two sides, and the ones you forget are the ones that get you. I've lost good soldiers to a spear from the caves while they were busy with the keep. Watch the Frostwolves, and watch the caves. The trolls don't care which flag you carry. Neither does a stew pot." }, { "You've the reverence of the Guard now. There's more rank above this, and I'd like to pin it on a soldier worth it." }, { "Wear the new insignia into the caves as proudly as onto the field.", after = 7170 } },
    exalted = { title = "Command", { "I've given out a great many insignias. The last of them is the Eye of Command, and you're as near to it as a soldier gets." }, { "There it is. Wear it, and the soldiers on that field will follow what you tell them, for as long as the battle lasts. They'll ask you where to stand, and you'll have to know, every time.", after = 7172 }, { "When you first walked up that road, I signed you up the way I sign up everybody, one more name for the list, one more pin on the map. I didn't think twice about it." }, { "I've spent my whole service telling soldiers where to go. You get good at it. You get so good that you stop noticing it's people you're moving about. Then the soldiers start looking to see which way one of the pins went before they pick their own way, and you start noticing again." }, { "So go and give your orders out there, and give them well. I'll be at the mouth of the valley with the spare insignias, and if you've an order for an old recruiter, I'll take it. It's been a long time since anybody gave me one I was glad of." }, { "Go on. They're waiting for you." } },
  },
  [729] = {
    start = { title = "The Call", { "You have come to the valley. Good. Out of the wind, stranger." }, { "For a long while there was no war here. The Frostwolves hunted, and raised their young, and buried their old, and the mountains kept us. Now the dwarves have come over the mountains with their banners, and the horns sound again in the valley, and every orc of this clan feels it in the chest." }, { "Nothing on this field is handed out. What honour you have, you carry off it yourself. Fight for the Frostwolf, and come back to me, and I will learn your name." } },
    friendly = { title = "Awakened", { "<Laggrond salutes you.>" }, { "You came back from the field, and you came back a soldier. I know it by how you stand." }, { "Take this insignia, and wear it always. It says friend of the clan.", after = 7163 }, { "That heat in your hands out there, the first time the horns blew and your feet moved before you told them to, that is your spirit answering. Some call that fear. It is the oldest part of you, remembering what it is for." }, { "The clan has a word for a soldier who comes back like that: friend. It does not give that word lightly. The clan is small, and old in these mountains, and it remembers every hand that was raised for it." } },
    honored = { title = "The Rage", { "My people never drank the demon's blood. I am proud of that every day of my life." }, { "And still, when the horns sound in this valley, something in me answers, and I do not like the answer. The battle rage. It climbs slowly in an old orc, but it climbs. My pulse heavy in my ears, the cold gone from my hands. For a while there is nothing but the next blow, and the next, and it is the best I have felt in years." }, { "That is why I keep it on a short rope. A clan that refused the demon must not come to love the fury for its own sake. I tell this to every soldier who reaches this rank, and most of them forget it by the next battle." }, { "The next insignia is yours. Keep the rope short, and remember who is holding it.", after = 7164 } },
    revered = { title = "Tales", { "<Laggrond roars.>" }, { "They are telling tales of you, soldier. In the keep, around the fires, on the towers. Even across the snow, they say, the dwarves go quiet at your name." }, { "Tales are a good thing, for a clan. They make the young ones brave. Nobody told me what they do to the one they are told about. They make you want more of them. The next fight bigger, the next tale louder. A warrior who fights for the tale is one charge away from a grave nobody remembers." }, { "The clan still tells one about a young orc who went into the snow alone after a great bear and came home with its hide. It does not tell that the bear's mate came down the pass while he knelt over the hide, admiring it, and that his brother, who had followed him out, stood in her way. The brother lived. He never walked the same again. I was the young orc. When the clan tells it at the fire, I tell the second half, and my brother nods." }, { "Keep the tale small." } },
    exalted = { title = "The Cold Head", { "Drek'Thar speaks of you. Out loud, to the elders, where everyone can hear. One of the elders asked me afterwards whether you were really as cold in battle as the soldiers say. I told him colder." }, { "The Eye of Command will be yours soon, and the soldiers of the valley will follow your word." }, { "There. The Eye is yours. They will go where you send them, and they will trust that you meant to send them there.", after = 7167 }, { "When the horns blow, the red comes up in most of us. In you it goes quiet, and you weigh the towers and the keep and the ground between, and choose. That is rarer than courage, and far rarer than rage. I have known a great deal of both, and the rage I have known from the inside." }, { "One thing more. You know what a battle costs the ones who carry the banner, and you go anyway. Go, then, and bring home as many as you can. The young ones will follow you into anything now, and when they get there, they should find it was worth the going. An orc who has followed a good leader once will follow the next one better." }, { "<Laggrond salutes.>" }, { "A cold head and a warm heart. The Frostwolf ask for no more than that." } },
  },
  [890] = {
    start = { title = "Few Words", { "You are of the Alliance. That will do for the gulch." }, { "I am Farsong. I keep the road to it, with my sisters of the Silverwing. The orcs keep the road on the other side. Between us is a valley that used to be forest, and a great deal of fighting." }, { "I do not say much. You will get used to it. Fight beside us, and bring me what you earn in there, and we will find out whether you stay. Trust is slow, in Ashenvale. The trees taught us that." } },
    friendly = { title = "The Trees", { "You have been in the gulch." }, { "Each talisman that comes to me from the gulch is a fight someone lived through. I hold it a moment before it goes with the others. My sisters call it a ritual. I like to know what a thing weighs before I trust it, and a talisman weighs exactly what it cost." }, { "The orcs are loud, and they like it that way. I have never needed to match them." }, { "My sisters say I talk to the trees. I do not. I listen to them, and they have more to say than most of the people who pass me on this road." } },
    honored = { title = "The Stumps", { "I walked this valley when it was forest." }, { "There was an oak at the far end, where the orcs' mill is now, older than anything I knew. A family of owls lived in it. I lived a whole season in its branches once, doing nothing at all. Nobody was in a hurry then." }, { "The axes came at night, the first time. By morning there was a track through the ferns, and by the end of that year there was a mill. The owls left the spring after. I do not know where they went. I have listened for them at every old oak between here and Astranaar, and I have not heard them yet." }, { "Much of the valley is stumps now. The orcs say they needed the wood. Perhaps they did. I have not forgiven it, and I do not mean to. It is quiet in me, and it will outlast the war." } },
    revered = { title = "The Glaive", { "One of my sisters fell at the far end of the gulch last spring. She went for their banner alone, because she was fast and young and certain. She was fast. She was young. She was wrong. They had waited for exactly that, behind the wall of their mill, and they did not need to be fast." }, { "I carried her glaive home. It hangs in my tent. I clean it once a moon. It does not need it. The edge is still nicked where she parried the first axe, and I have never filed it out. Nobody asks whose it is. Sentinels do not ask each other that. Her name I keep. That is what we do with each other's names, when the rest is gone." }, { "You have been in that gulch long enough to know what it costs to go after their banner. I tried to teach her patience, the whole of one summer. She was faster than my teaching." } },
    exalted = { title = "The Acorn", { "Last night I went to the far end of the gulch, to the old oak's stump beside their mill, while the orcs slept. The ground there is hard, packed flat by their boots. I dug at its foot with my hands, most of the night, and a sentry of theirs walked past me and never heard. I put an acorn in the hole, one of the old oak's own, that I had kept. Then I filled it in. It is a small hole. You would walk past it." }, { "Beside the acorn I put a talisman, the first one ever brought to me. I had kept it apart from the others for a long while without knowing what for. Now I know." }, { "It will not grow while there is fighting. Even if it did, they would cut it. I know all that. I did it anyway." }, { "One day the fighting will stop, and there will be one tree at the far end of the gulch that nobody has any use for. It will take a long time to grow. Oaks do, and I have learned to wait for them. When you pass that way, after, listen for owls. They will know the tree. Owls always do." } },
  },
  [889] = {
    start = { title = "Zug Zug", { "Zug zug, friend! Kelm Hargunth, who keeps the Outriders fed and mended, at your service, or I will be, once you've done something for them." }, { "That's how it works here. You fight in the gulch, the Outriders get to know you, and the better they know you, the more of my stock I'm allowed to sell you. Rations, bandages, the good stuff, all of it made for the gulch and no use anywhere else." }, { "For now, I'll mend your gear. That much I do for anybody in red. Then go on in, give the elves a hard day, and work up an appetite." } },
    friendly = { title = "Rations", { "There you are! The Outriders know your face now. That means rations." }, { "Here. Trail bread, dried meat, a little something for the nerves, all packed for the gulch. Outside the gulch they're no use to anyone, so don't go saving them for a long trip. They're made to be eaten between one fight and the next, standing up, with an elf arrow in the post beside your head." }, { "Half of a war is who ate last, and nobody sings about that half. An orc with something in his belly holds a flag a good deal longer than one without. I can't swing an axe like I used to. I can make sure the ones who do aren't hungry." }, { "Eat. Go fight. The bread will be here." } },
    honored = { title = "Bandages", { "That's the bandages open to you, then. Not that I like selling them as much as the bread." }, { "Every bandage I sell goes on somebody I know. That's the trouble with being the supplier. You hand out the rations at first light, and by dark the same faces come back for linen, and some of them don't come back at all. I know without asking who's due a new pack and who isn't due for anything any more." }, { "The elves aren't easy. They know that forest better than we ever will. They come out of the trees fast and quiet, and they don't give up, not ever, because it's their trees, and I'd fight the same way for mine." }, { "So, bandages. Buy a lot of them, and hand them round. The ones beside you will need them before you do." } },
    revered = { title = "Hellscream's Clan", { "Every orc in the Outriders can tell you about Grom. Most of them tell it louder than I do, and they leave the middle out." }, { "The Warsong are Hellscream's clan. When the Horde came across the sea, the Warchief sent us here for wood, and Grom took the job, and the forest fought back, and Grom did things to win that the whole Horde paid for. Then he paid for them himself, at the end, with his life, and freed us all doing it. We sing him. We're proud of him. We know the price too." }, { "And the axes haven't stopped. The wood is still wanted. Every log that leaves this valley costs somebody, an elf or an orc, and I know some of the names on our side. The elves know theirs." }, { "I ate my supper on one of their stumps once, and it made a good table. I haven't eaten there since." } },
    exalted = { title = "Something That Isn't for Killing", { "The Outriders don't ask who you are any more, not even the new ones. I'd say you earned that, but it's a small word for it." }, { "One day I mean to open this counter on a morning when nobody comes in hurt, and sell something that isn't for killing. Lamps. Good boots for walking, not running. Fishing line. Toys for the clan's young ones, the kind that only make a noise. A cradle or two, carved from wood nobody had to fight for. I've never had a morning like that." }, { "I've sold rations and bandages and repairs to the Outriders for so long that I've forgotten what it's like to hand somebody a thing and not wonder whether they'll be alive to use it up." }, { "I won't get my wish soon. I know that. The gulch isn't going anywhere, and neither are the elves, and neither are we. Most mornings start with somebody carried in off the field, and the first thing I sell is linen." }, { "When it comes, it'll be orcs wanting boots, and nobody waiting on linen. I don't know what I'll say to them. Something about the boots, probably." } },
  },
  [509] = {
    start = { title = "One Line", { "Field Marshal Oslight, of the League of Arathor. I've been on my feet since before dawn, so you'll have the short version." }, { "The League's oath is one line, and I've given it more mornings than I gave the walls I grew up on. I'll not tell you it goes well every day. It goes well enough that I get up for it, and so do the rest of us." }, { "If you're of the Alliance and you can hold a weapon, there's a place for you in the basin. What it's for, you'll learn in it." } },
    friendly = { title = "Roads", { "You've been in the basin, then, and had a taste of what it's for." }, { "We fight over what the land can carry. Every point the League holds is a road open to the front, with something going up it to an army that needs it. Every point the enemy holds is a road shut, and the same things going the other way." }, { "The carts are moving our way these days. The quartermasters noticed before I did. They're the first to know when a cart is late, so they're the first to know when it isn't." }, { "Keep at it. The League needs fighters who understand that holding a mill can matter as much as winning a duel. Most learn it the hard way. A few never do, and I write to their families." } },
    honored = { title = "Stromgarde", { "I come from Stromgarde." }, { "Stromgarde had the best walls I ever stood on, and a king whose banner I'd have followed anywhere. I served there as a young man, on those walls. I knew every stone of my stretch of them, and which ones rocked, and which I'd have trusted with my life." }, { "I hear my stretch of wall is in other hands now, and I expect the stones that rocked have fallen. The people are scattered: some here, some in Stormwind's streets, some nowhere I can name. When the League took its oath, it took it for them." }, { "I don't expect to see Stromgarde whole again. I'm too old, and the walls are too far gone. But every cart that leaves the basin under our banner feeds someone who used to call that keep home." } },
    revered = { title = "Benefactors", { "Stormwind pays for us. That's no secret. The coin, the arms, the horses, the bread, even the nails in the palisade: our benefactors' purse." }, { "What the benefactors want for it, I don't ask. Some of the families who farmed this land before the war are here at Refuge Pointe, mending my soldiers' boots, and they don't ask me either." }, { "I've made my peace with not asking, mostly. A farm feeds people whoever holds the deed. The people of Stromgarde will eat from it either way, and that's what I swore. I walk past the families' tents most evenings. The children have started saluting me, badly, and I salute back, properly, because someone should show them how." }, { "So fight for the people who'll eat from those farms, and leave the purse to the men who fill it. A clerk would tell you a prettier story. I keep to this one myself, on the days I manage it." } },
    exalted = { title = "The Wall", { "I ran, once." }, { "The night Stromgarde's walls were lost, I was on them. I had a post and a captain and a sword I knew how to use, and when the gate went, I ran. Down the hill, into the dark, and on until the noise stopped behind me. I've said since that the wall was already lost, and it was. One more sword would have been one more body. I ran because I was young and frightened, and the dark at the bottom of the hill felt like living." }, { "A field marshal's record says where he stood. Mine says Stromgarde, and leaves the hill out." }, { "The reports come up to me every evening from the basin, who held and who broke. And the recruits who held a point beside you hold the next one too. That spreads, in an army. Fear spreads, and so does staying put." }, { "If the League ever holds the basin for good, I mean to go up the hill to the keep, and be first onto the wall. Somebody of Stromgarde ought to stand on it to the end this time, and I'd like it to be the one who ran." } },
  },
  [510] = {
    start = { title = "The Name", { "Deathmaster Dwire, of the Defilers. The living find the title alarming. I have never had a reason to change it." }, { "The Defilers hold Arathi Basin for the Horde, or will, once the League stops arguing the point. Everything that basin grows or digs or cuts, the Horde has a use for. The League has a use for it too. That's the quarrel, and I mean to win it." }, { "The name Defilers? We chose it. The League would have found us a worse one, and I prefer to be insulted accurately." }, { "There's work in the basin for anyone of the Horde. Go and spoil a human's harvest, then tell me about it." } },
    friendly = { title = "Spite", { "Back from the basin, and the League a little hungrier for it. Good." }, { "Everyone in the Horde fights for something. Some talk of honour, some of the land. The Forsaken have a reason too, and I'll not dress it up for you. Spite." }, { "When we came up out of the ground, the living met us with torches and holy water. Every morning since, we have got up and gone on existing at them. There is no satisfaction like it." }, { "Don't take it for a small thing. Spite never runs out. It needs no food, no sleep, no letters from home. A soldier who fights for a home can lose it. Nobody has ever managed to take my spite off me, and the League has tried, at length." }, { "Keep at it." } },
    honored = { title = "What They Shout", { "The League's soldiers shout at us across the basin. Most of it is the usual: rot, curses, the Light. Every so often one of them says something worth the hearing." }, { "At the farm last week, a young soldier of Stromgarde shouted that the field I was holding had been his grandfather's. He shouted it twice, as if I might not have understood, and then he came at me with it." }, { "I held the field. That's what I'm for. But the thought of the old man stayed with me afterwards, all through the night, and that is not what I'm for at all." }, { "So I gave the matter some thought, the way a Forsaken does when the nights are long. The humans of Stromgarde want their fields back. They would like Arathi to be theirs again, and the past with it, and us to lie down and stay down. They can have none of it. That's spite, and I'll keep it, grandfather or no grandfather." }, { "The Defilers hold their fields well. Keep holding them." } },
    revered = { title = "The Watch", { "The orcs at Hammerfall made warding signs when I first came, the old kind, when they thought I wasn't looking. I didn't mind. I've been warded against by better." }, { "Then a sergeant of theirs, a big scarred cheerful brute with half an ear, took to bringing me the first news of the day before anyone else had it. Who held the mine. Who'd lost the stables. Who'd fallen, and whether they'd get up again. As if I might want it first. I did." }, { "The Defilers are no family. Half the orcs think I smell, and they're right. But when one of ours goes down at the smithy, it's orcs and trolls and tauren and Forsaken who go back for them together, under the same arrows, and nobody stops to ask what anyone else is." }, { "Last night the sergeant took the long watch on the gate, so that I wouldn't have to explain to the new recruits why I don't sleep. Nobody asked him to. He told them I was at my prayers. I let him." } },
    exalted = { title = "The Other Reason", { "I said spite, when you were new to us. It's true, and it's the answer I like best to give, because it frightens the living and costs me nothing." }, { "There's another, underneath." }, { "When my people went looking for a place in the world, every door in it was shut against us but one, and it was the Horde's. The Horde took its time with us. Some of the orcs wanted nothing to do with the dead. Some of the tauren spoke for us anyway, and the Warchief heard them. Nobody else did, and I haven't forgotten who did." }, { "Everything the Defilers take from that basin goes home, to the people who opened that door. The ore goes to their forges, and the grain to their tables. I'll never eat a crumb of it, and that suits me. I keep that reason under the spite, where the League can't get at it." }, { "You've held a good deal of that basin for the people behind that door. The League has noticed. So have I, and so has the sergeant." }, { "Take the Defilers' thanks. Mine is the one you'll have to ask me for twice." } },
  },
}
-- (the places Classic Era's client names otherwise, swapped in there, the longest first)
ns.classicNames = {  }
